def flatten_php_form(data, parent_key=""):
    """Konvertiert nested dict/list zu PHP-Bracket-Form für x-www-form-urlencoded.

    Beispiel: {'settings': [{'id_slave': '29524'}]}
    →        [('settings[0][id_slave]', '29524')]

    Wird von Duplikium V4 verlangt für Endpoints die Arrays nehmen (z.B. setSettings.php).
    Flache Dicts ohne Nesting bleiben unverändert (Backwards-Compat zu getAccounts etc.).
    """
    items = []
    if isinstance(data, dict):
        for k, v in data.items():
            new_key = f"{parent_key}[{k}]" if parent_key else str(k)
            if isinstance(v, (dict, list)):
                items.extend(flatten_php_form(v, new_key))
            elif v is None:
                items.append((new_key, ""))
            elif isinstance(v, bool):
                items.append((new_key, "1" if v else "0"))
            else:
                items.append((new_key, str(v)))
    elif isinstance(data, list):
        for i, v in enumerate(data):
            new_key = f"{parent_key}[{i}]"
            if isinstance(v, (dict, list)):
                items.extend(flatten_php_form(v, new_key))
            elif v is None:
                items.append((new_key, ""))
            elif isinstance(v, bool):
                items.append((new_key, "1" if v else "0"))
            else:
                items.append((new_key, str(v)))
    return items

@app.after_request
def cors(r):
    r.headers["Access-Control-Allow-Origin"] = "*"
    # sb-token gehört dazu, sonst blockt der Browser den Admin-Endpoint schon im
    # Preflight ("Failed to fetch", 15.08.2026 live aufgetreten).
    r.headers["Access-Control-Allow-Headers"] = "Content-Type, Authorization, ma-token, ma-account, dup-token, dup-user, sb-token"
    # PATCH/DELETE seit 31.08.2026: der Kaufplan aendert und loescht Zeilen, und
    # ohne die Methoden hier scheitert schon der Preflight — der Browser meldet
    # nur "Failed to fetch", was wie ein Netzfehler aussieht und keiner ist.
    # Exakt dieselbe Falle wie beim sb-token-Header eine Zeile drueber.
    r.headers["Access-Control-Allow-Methods"] = "GET, POST, PATCH, DELETE, OPTIONS"
    return r

@app.route("/")
def index():
    # Optional (nur für lokale PC-Installationen): Frontend LIVE von einer URL holen,
    # damit prophos.html auf den PCs nie veraltet — Updates laufen dann weiter normal
    # über GitHub/Cloudflare, ohne dass auf jedem PC etwas nachgezogen werden muss.
    # Aktivierung per Env-Var PROPHOS_FRONTEND (setzt start-local-backend.bat).
    # Ohne die Var bleibt das Verhalten unverändert (Railway ist damit nicht betroffen).
    # Bei jedem Fehler/Timeout: Fallback auf die lokale Datei, damit der PC offline
    # weiterarbeiten kann.
    # SCHUTZ (07.10.2026, Finn: „dass man die Software, das Frontend und das Backend nicht kopieren kann"): auf Railway liefert
    # „/" die Oberfläche NICHT mehr aus — sie lag dort für jeden ohne Login offen. Railway ist nur API; die Seite gibt es über
    # pages.dev (dort davor Cloudflare Access) bzw. auf den PCs über localhost:5000.
    if (os.environ.get("RAILWAY_ENVIRONMENT") or os.environ.get("RAILWAY_GIT_COMMIT_SHA") or "").strip():
        return Response('<!doctype html><meta charset="utf-8"><title>Prophos</title>'
                        '<p style="font-family:system-ui">Prophos: <a href="https://prophos.pages.dev/prophos">prophos.pages.dev</a></p>',
                        mimetype="text/html")
    remote = (os.environ.get("PROPHOS_FRONTEND") or "").strip()
    if remote:
        # Seit 07.10.2026 zuerst mit dem PC-Schlüssel von Railway (pages.dev steht hinter Cloudflare Access, ein Server-Abruf
        # ohne Anmeldung bekäme dort nur die Login-Seite); pages.dev und die lokale Datei bleiben Rückfall.
        r0 = _code_holen("/code/datei/prophos.html", timeout=15)
        if r0 is not None and len(r0.content) > 50000 and b"OS_TAB_BUILD" in r0.content:
            return Response(r0.content, mimetype="text/html")
        try:
            r = requests.get(remote, timeout=10)
            if r.ok and len(r.content) > 50000 and b"OS_TAB_BUILD" in r.content:
                return Response(r.content, mimetype="text/html")
            print(f"[frontend] Remote lieferte HTTP {r.status_code} / {len(r.content)} Bytes — nutze lokale Datei")
        except Exception as e:
            print(f"[frontend] Remote-Fetch fehlgeschlagen ({type(e).__name__}) — nutze lokale Datei")
    # Serve prophos.html if present, otherwise fall back to old index.html
    if os.path.exists("prophos.html"):
        return send_from_directory(".", "prophos.html")
    return send_from_directory(".", "index.html")

# ── Frontend-Version für den Build-Wächter (25.09.2026, Koordination: PC-Tabs liefen tagelang auf altem Stand — Mikes
# pc-l5o8bv auf .544, aktuell .595). Der Wächter in prophos.html holt /mt5-copier/VERSION von der eigenen Origin; auf
# localhost:5000 gab es die Route nicht (404), also blieb er still und der offene Tab alt (der Selbst-Update-Watcher
# aktualisiert nur Backend/Copier). Quelle wie beim Frontend-Proxy oben: im Lokal-Modus (PROPHOS_FRONTEND) dieselbe
# Remote-Origin, damit Version und ausgeliefertes HTML zusammenpassen; sonst (Railway) die Datei im Repo. 30 s gecacht,
# CORS kommt aus dem gemeinsamen after_request. ──
_frontend_ver = {"at": 0.0, "wert": None}
_FRONTEND_VER_RE = re.compile(r"^\d{4}-\d{2}-\d{2}\.\d+$")

@app.route("/mt5-copier/VERSION", methods=["GET"])
def frontend_version():
    now = time.time()
    if _frontend_ver["wert"] and now - _frontend_ver["at"] < 30:
        wert = _frontend_ver["wert"]
    else:
        wert = None
        remote = (os.environ.get("PROPHOS_FRONTEND") or "").strip()
        if remote:
            r0 = _code_holen("/code/stand")      # 07.10.2026: zuerst Railway (pages.dev hinter Cloudflare Access)
            try:
                v0 = str(((r0.json() or {}).get("version") if r0 is not None else "") or "").strip()
                if _FRONTEND_VER_RE.match(v0):
                    wert = v0
            except Exception:
                pass
        if remote and not wert:
            try:
                m = re.match(r"^(https?://[^/]+)", remote)
                if m:
                    r = requests.get(m.group(1) + "/mt5-copier/VERSION", timeout=6, headers={"Cache-Control": "no-cache"})
                    t = (r.text or "").strip()
                    if r.ok and _FRONTEND_VER_RE.match(t):
                        wert = t
            except Exception as e:
                print(f"[frontend] VERSION remote fehlgeschlagen ({type(e).__name__}) — nutze lokale Datei")
        if not wert:
            try:
                with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "mt5-copier", "VERSION"), "r", encoding="utf-8") as f:
                    t = f.read().strip()
                wert = t if _FRONTEND_VER_RE.match(t) else None
            except Exception:
                wert = None
        if wert:
            _frontend_ver.update(at=now, wert=wert)
    if not wert:
        return Response("", status=404, mimetype="text/plain")
    resp = Response(wert, mimetype="text/plain")
    resp.headers["Cache-Control"] = "no-store"
    return resp

# ── TopstepX Proxy ──
@app.route("/api/<path:path>", methods=["GET","POST","OPTIONS"])
def tsx_proxy(path):
    if request.method == "OPTIONS": return "", 200
    h = {"Content-Type": "application/json"}
    t = request.headers.get("Authorization", "")
    if t: h["Authorization"] = t
    try:
        r = requests.request(request.method, f"{TSX_BASE}/api/{path}",
            json=request.get_json(silent=True), headers=h, timeout=10)
        return Response(r.content, status=r.status_code, content_type="application/json")
    except Exception as e:
        return jsonify({"error": str(e), "success": False}), 500

# ── MetaApi Proxy ──
@app.route("/ma/<path:path>", methods=["GET","POST","OPTIONS"])
def ma_proxy(path):
    if request.method == "OPTIONS": return "", 200
    token      = request.headers.get("ma-token", "")
    account_id = request.headers.get("ma-account", "")
    h = {"Content-Type": "application/json", "auth-token": token}
    if account_id and path == "account":
        url = f"{MA_BASE}/users/current/accounts/{account_id}/account-information"
    elif account_id:
        url = f"{MA_BASE}/users/current/accounts/{account_id}/{path}"
    else:
        url = f"{MA_BASE}/users/current/{path}"
    try:
        r = requests.request(request.method, url,
            json=request.get_json(silent=True), headers=h, timeout=15, verify=False)
        return Response(r.content, status=r.status_code, content_type="application/json")
    except Exception as e:
        return jsonify({"error": str(e)}), 500

# ── MT5-Copier Panel-Proxy (Etappe 3, 15.08.2026) ──
# prophos.html erreicht darueber die Panel-API des eigenen Hedge-Copier-Stacks
# auf DIESEM PC (127.0.0.1:8770, siehe mt5-copier/panel.py). Bewusst nur
# localhost: der Copier ist eine Pro-PC-Angelegenheit — auf Railway existiert
# kein Panel, dort antwortet die Route sauber mit 502 und das Frontend zeigt
# "nur am lokalen PC verfuegbar". Die Duplikium-Logik bleibt komplett
# unberuehrt; das hier ist die parallele Schnittstelle zum eigenen Copier.
COPIER_PANEL = "http://127.0.0.1:8770"

@app.route("/copier/<path:path>", methods=["GET","POST","OPTIONS"])
def copier_proxy(path):
    if request.method == "OPTIONS": return "", 200
    # SICHERHEIT (Review 15.08.2026): Das Panel schuetzt sich selbst nur, solange
    # es direkt angesprochen wird — es bindet an 127.0.0.1 und prueft Host+Origin.
    # Dieser Proxy darf diese Grenze NICHT aufweichen. Zwei Riegel:
    #  1) Nur lokale Aufrufer. app.py lauscht auf 0.0.0.0 (Railway/LAN), aber der
    #     Copier ist eine reine Loopback-Sache. Ein LAN-Geraet (fremde remote_addr)
    #     darf hier nichts schalten — sonst koennte es Accounts auf 'live' setzen.
    #  2) Browser-Origin durchreichen, damit die Origin-Pruefung des Panels wieder
    #     greift (schuetzt gegen Drive-by-POSTs fremder Seiten trotz CORS '*').
    if request.remote_addr not in ("127.0.0.1", "::1", "::ffff:127.0.0.1"):
        return jsonify({"ok": False, "copier_offline": True,
                        "error": "Copier ist nur lokal auf dem PC selbst erreichbar."}), 403
    h = {"Content-Type": "application/json"}
    origin = request.headers.get("Origin")
    if origin: h["Origin"] = origin
    try:
        # master-order braucht mehr Luft als der Rest (Review-Blocker 15.08.2026):
        # ein zu frueher Proxy-Abbruch haette dem Frontend 'keine Order' gemeldet,
        # waehrend die Order Sekunden spaeter doch platziert wird (Doppel-Order-
        # Pfad). Seit 287644d darf der Bot bis 300s laufen (SL/TP-Band-Scan) —
        # die 60s hier waren am alten 45s-Stand kalibriert und rissen die Kette
        # wieder auf (Offene Punkte 215/221); mit Remote-Signalen (28.08.2026)
        # sitzt dann niemand am PC, der es merkt. Der aeussere Timeout ist die
        # Obergrenze der Wahrheit: 310s = Bot-Maximum + Puffer. master-close
        # (28.08.2026, Remote-Close) faehrt denselben Band-Scan — gleiche Luft.
        # tv-order (30.08.2026, Orbit-Puls Schritt 2) gehoert in dieselbe
        # Klasse: der Bot darf 180s laufen (vier Warte-Etappen im Browser plus
        # 25s Bestaetigungsfenster), ein frueher Proxy-Abbruch waere hier
        # derselbe Doppel-Order-Pfad wie bei master-order.
        # tv-konto (21.09.2026, Futures-Puls Neuaufbau Schritt 2): startet bei
        # Bedarf TradingView und wartet, bis der Broker wieder verbunden ist —
        # das Panel gibt dem Bot 260 s (seit 2b: ab-/anmelden). Hier wird nichts gesendet, ein frueher
        # Abbruch waere also kein Doppel-Order-Pfad, aber eine falsche Absage.
        # tv-lesen / tv-close (24.09.2026, Orbit-V2-Rundgang und -Schließen): der Bot schaltet
        # Konten um und wartet auf frische Reader-Stände — Panel-Timeout bis 165 s+. Mit 25 s
        # brach der Proxy ab, während der Bot weiterklickte (PC-Agent-Befund).
        # hedge-solo (24.09.2026, Winning-Day-Gegenhedge): das Panel wartet bis 14 s auf die
        # Quittung des Copiers — 25 s waeren knapp, ein Proxy-Abbruch saehe wie „nicht gesendet" aus.
        # tsx-konto / tsx-lesen / tsx-inventar / tsx-close (30.09.2026, Topstep-Paket Etappe S): das Panel gibt dem Bot 170 s
        # (tsx-konto) bzw. 150 s — mit den 25 s von bisher brach der Proxy ab, während der Bot unter TV_ORDER_LOCK
        # weiterklickte (order_signale 99e6087a, 27.09. ReadTimeout). Das Frontend meldete „nichts gesendet", ein
        # erneuter Start hätte ein zweites Mal platziert: derselbe Doppel-Order-Pfad wie master-order.
        _tmo = (310 if path in ("master-order", "master-close", "tv-order", "tv-lesen", "tv-close",
                                "tsx-konto", "tsx-lesen", "tsx-inventar", "tsx-close")
                else 270 if path == "tv-konto" else 40 if path == "hedge-solo" else 25)
        r = requests.request(
            request.method, f"{COPIER_PANEL}/api/{path}",
            params=request.args,
            json=request.get_json(silent=True) if request.method == "POST" else None,
            headers=h, timeout=_tmo)
        return Response(r.content, status=r.status_code, content_type="application/json")
    except Exception as e:
        return jsonify({"ok": False, "copier_offline": True,
                        "error": f"Copier-Panel auf diesem PC nicht erreichbar ({type(e).__name__})"}), 502

# ── Stack-Neustart per Knopf (15.08.2026, Finns Wunsch) ──
# Das Hand-Ritual — CMD-Fenster zu, taskkill python, start-alles.bat — als EIN
# Klick im MT5-Tab. Killt bewusst auch DIESES Backend; die .bat startet alles
# frisch, laufende Instanzen schuetzen sich selbst (Copier-Status-Sperre,
# Panel/Backend-Port-Probe). Nur Lokal-Modus + nur Loopback (gleiche Riegel
# wie der Copier-Proxy — ein LAN-Geraet darf den Stack nicht neu starten).
#
# 31.08.2026 (Finn: "bau mal einen Button, der alle offenen CMD schliesst — ich
# muss die immer von Hand schliessen"): der Kill war bis heute eine WHITELIST
# von fuenf Fenstertiteln. Die trifft genau die Fenster, die start-alles.bat
# selbst mit "start <Titel> cmd /c ..." oeffnet — und sonst keines. Alles
# andere ueberlebt und stapelt sich: das Fenster von start-alles.bat SELBST
# (autostart-einrichten.bat startet es mit LEEREM Titel, es laeuft also unter
# dem Standardtitel), jedes von Hand doppelgeklickte .bat, und jede Huelle,
# deren Titel sich seit dem Start geaendert hat. Auf Finns Screenshot standen
# sieben Konsolen; nach "Alles neu starten" blieben die titellosen stehen.
# Eine Whitelist kann das prinzipiell nicht loesen — sie kennt nur, was sie
# selbst geoeffnet hat. Deshalb jetzt umgekehrt: ALLE cmd.exe, egal woher.
# Das ist Finns Ansage ("alle sieben Fenster, egal welche") und auf diesen PCs
# auch richtig: was dort in einer Konsole laeuft, gehoert zum Stack und wird
# im selben Zug neu gestartet.
# Der Helfer ist deshalb ein POWERSHELL-Skript und kein .bat mehr: ein .bat
# laeuft selbst in einer cmd.exe und wuerde sich beim Blanko-Kill als Erstes
# selbst beenden — start-alles.bat wuerde nie erreicht. powershell.exe ist vom
# cmd-Kill nicht betroffen und ueberlebt ihn. Die Datei liegt bewusst im
# Klartext in %TEMP% (kein -EncodedCommand), damit auf dem PC nachlesbar
# bleibt, was der Knopf getan hat.
@app.route("/local/restart-stack", methods=["POST", "OPTIONS"])
def local_restart_stack():
    if request.method == "OPTIONS":
        return "", 200
    if request.remote_addr not in ("127.0.0.1", "::1", "::ffff:127.0.0.1"):
        return jsonify({"ok": False, "msg": "Nur lokal auf dem PC selbst erlaubt."}), 403
    if os.name != "nt" or not (os.environ.get("PROPHOS_FRONTEND") or "").strip():
        return jsonify({"ok": False, "msg": "Nur im Lokal-Modus (PROPHOS_FRONTEND) verfuegbar."}), 403
    bat = (os.environ.get("PROPHOS_STACK_BAT") or r"C:\mt5-copier\start-alles.bat").strip()
    if not os.path.exists(bat):
        return jsonify({"ok": False, "msg": f"start-alles.bat nicht gefunden: {bat}"})
    if "'" in bat:
        # Ein einfaches Anfuehrungszeichen wuerde das PS-Literal unten aufbrechen.
        return jsonify({"ok": False, "msg": "Pfad mit ' wird nicht unterstuetzt: " + bat})
    import subprocess
    import tempfile
    url = ("https://raw.githubusercontent.com/finntraidingview-cmd/Prophos/"
           "main/mt5-copier/start-alles.bat")
    helper = os.path.join(tempfile.gettempdir(), "prophos-restart-stack.ps1")
    skript = f"""# Von Prophos erzeugt — Knopf "Alles schliessen & neu starten".
$ErrorActionPreference = 'SilentlyContinue'
$ProgressPreference = 'SilentlyContinue'
# Antwort ans Frontend rausgehen lassen, bevor das Backend stirbt.
Start-Sleep -Seconds 2
# 1) ALLE Konsolenfenster — und zwar ZUERST: start-copier.bat & Co. sind
#    Neustart-Schleifen, ein zuerst beendetes python.exe waere in 10 s zurueck.
Get-Process cmd | Stop-Process -Force
# 2) Danach die Prozesse selbst. Trifft absichtlich auch dieses Backend.
Get-Process python, pythonw | Stop-Process -Force
Start-Sleep -Seconds 2
# 3) start-alles.bat haelt alles ausser sich selbst aktuell — eine LAUFENDE
#    Batchdatei darf man nicht ueberschreiben, sie kann es also nicht selbst
#    tun. Hier geht es: der Kill oben hat gerade alles beendet, die Datei ist
#    garantiert nicht offen. Best effort — schlaegt der Download fehl oder
#    kommt er zu kurz an, bleibt schlicht der alte Stand.
$bat = '{bat}'
# Seit 07.10.2026 (Repo privat): zuerst Railway mit dem PC-Schlüssel (code_token.txt neben der .bat), sonst GitHub.
$tok = ''
try {{ $tok = (Get-Content (Join-Path (Split-Path -Parent $bat) 'code_token.txt') -TotalCount 1 -ErrorAction Stop).Trim() }} catch {{ }}
$ok = $false
if ($tok) {{ try {{ Invoke-WebRequest 'https://web-production-bec81.up.railway.app/code/datei/mt5-copier/start-alles.bat' -Headers @{{'X-Code-Token'=$tok}} -OutFile "$bat.newh" -TimeoutSec 20 -UseBasicParsing; $ok = $true }} catch {{ }} }}
if (-not $ok) {{ try {{ Invoke-RestMethod '{url}' -OutFile "$bat.newh" -TimeoutSec 20 }} catch {{ }} }}
if (Test-Path "$bat.newh") {{
  if ((Get-Item "$bat.newh").Length -ge 700) {{ Move-Item -Force "$bat.newh" $bat }}
  else {{ Remove-Item -Force "$bat.newh" }}
}}
# 4) Frisch hochfahren.
Start-Process -FilePath $bat -WorkingDirectory (Split-Path -Parent $bat)
"""
    # utf-8-SIG (mit BOM): Windows PowerShell 5.1 liest eine .ps1 OHNE BOM als
    # ANSI und verstuemmelt dabei die Umlaute/Gedankenstriche in den Kommentaren.
    # Harmlos waere das nur, solange nichts davon je aus einem Kommentar rutscht
    # — der BOM macht die Frage gegenstandslos.
    with open(helper, "w", encoding="utf-8-sig") as f:
        f.write(skript)
    DETACHED_PROCESS = 0x00000008
    CREATE_NEW_PROCESS_GROUP = 0x00000200
    subprocess.Popen(["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass",
                      "-WindowStyle", "Hidden", "-File", helper],
                     creationflags=DETACHED_PROCESS | CREATE_NEW_PROCESS_GROUP,
                     close_fds=True, cwd=os.path.dirname(bat))
    print("[stack] Neustart angestossen — ALLE Konsolen werden geschlossen, "
          "dieses Backend wird mitgekillt.", flush=True)
    return jsonify({"ok": True, "msg": "Alle Konsolen werden geschlossen, Stack startet neu."})

# ── Duplikium Connect (Basic Auth → Token) ──
@app.route("/duplikum/connect", methods=["POST","OPTIONS"])
def duplikum_connect():
    """
    Body: {"email": "...", "password": "..."}
    Macht Basic-Auth-POST gegen getToken.php und gibt Token zurück.
    Token + Creds werden in-memory gecached für Auto-Refresh.
    """
    if request.method == "OPTIONS": return "", 200
    data = request.get_json(silent=True) or {}
    email    = (data.get("email") or "").strip()
    password = data.get("password") or ""
    if not email or not password:
        return jsonify({"ok": False, "error": "email und password sind nötig"}), 400

    try:
        r = requests.post(
            f"{DUP_BASE}/access/getToken.php",
            auth=(email, password),
            timeout=15
        )
        # Duplikium gibt entweder JSON {token: "..."} oder den Token direkt als Plain-Text zurück.
        # Wir behandeln beide Fälle defensiv.
        token = None
        try:
            d = r.json()
            if isinstance(d, dict):
                token = d.get("token") or d.get("access_token") or (d.get("data") or {}).get("token")
            elif isinstance(d, str):
                token = d
        except Exception:
            # Plain-Text-Response
            txt = (r.text or "").strip().strip('"')
            if txt and len(txt) < 2000 and " " not in txt:
                token = txt

        if not r.ok or not token:
            return jsonify({
                "ok": False,
                "status": r.status_code,
                "error": "Login fehlgeschlagen — prüfe E-Mail/Passwort und ob 'Enable access' im Trade-Copier-Dashboard aktiviert ist.",
                "raw": (r.text or "")[:300]
            }), 401

        # Cache (Memory only)
        duplikum_sessions[email] = {
            "token": token,
            "password": password,
            "last_refresh": time.time()
        }
        return jsonify({"ok": True, "token": token, "email": email})

    except requests.exceptions.RequestException as e:
        return jsonify({"ok": False, "error": f"Netzwerkfehler: {e}"}), 502
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500

def refresh_duplikum_token(email):
    """Holt einen neuen Token. Nutzt gecachte Creds ODER dauerhafte Env-Creds
    (überlebt Restarts/Worker-Wechsel). Returns neuer Token oder None."""
    s = duplikum_sessions.get(email)
    password = (s or {}).get("password")
    # Fallback: dauerhafte Env-Creds, falls der In-Memory-Cache leer ist
    # (z.B. nach Railway-Restart oder in einem anderen Gunicorn-Worker).
    if not password and email and DUP_EMAIL and email.lower() == DUP_EMAIL.lower():
        password = DUP_PASSWORD
    if not password:
        return None
    try:
        r = requests.post(
            f"{DUP_BASE}/access/getToken.php",
            auth=(email, password),
            timeout=15
        )
        token = None
        try:
            d = r.json()
            if isinstance(d, dict):
                token = d.get("token") or d.get("access_token") or (d.get("data") or {}).get("token")
            elif isinstance(d, str):
                token = d
        except Exception:
            txt = (r.text or "").strip().strip('"')
            if txt and len(txt) < 2000 and " " not in txt:
                token = txt
        if r.ok and token:
            # Session (neu) aufbauen, damit Folge-Refreshes wieder aus dem Cache gehen
            duplikum_sessions[email] = {
                "token": token,
                "password": password,
                "last_refresh": time.time()
            }
            print(f"[duplikum] 🔄 Token refreshed für {email}")
            return token
    except Exception as e:
        print(f"[duplikum] ⚠️ Refresh error: {e}")
    return None

# ── Duplikium Session-Handout (25.08.2026) ──
# Flotte + Live-Lots im Frontend brauchen den Duplikium-Token, der aber nur im
# localStorage des Browsers lebt, der ihn mal per Login geholt hat. Lief er ab
# (401 -> dupLogout), starben alle Duplikium-Anzeigen auf pages.dev, bis jemand
# die Creds neu eintippt (Finns Fund 25.08.: Lots-Chips um 19:02 da, 19:52 weg).
# Railway haelt ueber den Auto-Connect-Daemon ohnehin einen frischen Token —
# dieser Endpoint reicht ihn an EINGELOGGTE Prophos-User weiter (sb-token-
# Pruefung wie /admin/overview; ohne Login gibt es nichts).
@app.route("/duplikum/session", methods=["GET", "OPTIONS"])
def duplikum_session():
    if request.method == "OPTIONS":
        return "", 200
    token = (request.headers.get("sb-token") or "").strip()
    if not token:
        return jsonify({"ok": False, "error": "Nicht angemeldet"}), 401
    uid = ""
    try:
        r = _auth_user_anfrage(token)
        uid = str((r.json() or {}).get("id") or "") if r.status_code == 200 else ""
        if not uid:
            return jsonify({"ok": False, "error": "Nicht angemeldet"}), 401
    except Exception:
        return jsonify({"ok": False, "error": "Anmeldung nicht pruefbar"}), 502
    # Token-Quelle ist DIESELBE wie beim Waechter: duplikum_credentials aus
    # Supabase (ueberlebt Restarts). Der erste Wurf nahm DUP_EMAIL-Env-Creds —
    # die sind auf Railway aber nie gesetzt (Fund 25.08.: Endpoint gab 503,
    # waehrend der Waechter munter pollte). Bevorzugt die Zeile des anfragenden
    # Users, sonst irgendeine — es ist EIN geteiltes Duplikium-Konto.
    creds = None
    if SUPABASE_SERVICE_KEY:
        try:
            rows = [c for c in dup_creds_lesen()   # 60-s-Cache, geteilt mit dem Wächter (01.10.2026)
                    if (c.get("email") or "").strip()]
            creds = next((c for c in rows if str(c.get("user_id")) == uid), None) \
                or (rows[0] if rows else None)
        except Exception as e:
            print(f"[duplikum] ⚠️ session creds: {type(e).__name__}: {e}", flush=True)
    if not creds and DUP_EMAIL:
        creds = {"email": DUP_EMAIL, "password": DUP_PASSWORD}
    if not creds:
        return jsonify({"ok": False, "error": "Keine Duplikium-Zugaenge hinterlegt"}), 503
    tok = wt_email_token(creds)
    if not tok:
        return jsonify({"ok": False, "error": "Duplikium-Login fehlgeschlagen"}), 502
    return jsonify({"ok": True, "token": tok, "email": (creds.get("email") or "").strip()})


# ── Duplikium Generic Proxy ──
@app.route("/duplikum/<path:path>", methods=["GET","POST","OPTIONS"])
def duplikum_proxy(path):
    """
    Generischer Proxy für alle Duplikium V4 Endpoints.
    Frontend schickt:
      - dup-token Header (Bearer Token)
      - dup-user  Header (Email — für Auto-Refresh nötig)
      - Body als JSON (wir konvertieren zu application/x-www-form-urlencoded
        weil Duplikium keine JSON-Body unterstützt)
    """
    if request.method == "OPTIONS": return "", 200
    token = request.headers.get("dup-token", "")
    email = request.headers.get("dup-user", "")
    if not token:
        return jsonify({"error": "dup-token Header fehlt"}), 401

    url = f"{DUP_BASE}/{path}"

    # JSON Body vom Frontend → form-encoded für Duplikium
    # WICHTIG: Duplikium V4 will PHP-Bracket-Notation für nested arrays
    # (z.B. setSettings.php braucht settings[0][id_slave]=...).
    # Flat dicts wie {email: 'x'} bleiben dabei unverändert.
    body_data = None
    if request.method == "POST":
        raw = request.get_json(silent=True) or {}
        body_data = flatten_php_form(raw) if raw else None

    path_norm = path.lower()
    is_cacheable = request.method == "POST" and path_norm in DUP_CACHEABLE
    # Read-Endpoints dürfen schneller aufgeben (12s) — hängt Duplikum länger, hilft
    # Warten eh nicht; Mutationen behalten die vollen 20s.
    req_timeout = 12 if is_cacheable else 20

    def do_request(tok):
        h = {
            "Authorization": f"Bearer {tok}",
            "Content-Type": "application/x-www-form-urlencoded"
        }
        return requests.request(
            request.method,
            url,
            params=request.args,
            data=body_data,  # Dict → automatisch form-encoded
            headers=h,
            timeout=req_timeout
        )

    def do_full_request():
        """Ein echter Upstream-Call inkl. 401-Refresh. Gibt (status, content, ctype, new_tok) zurück."""
        r = do_request(token)
        refresh_email = email or DUP_EMAIL
        if r.status_code == 401 and refresh_email:
            # SICHERHEIT (04.08.2026, Review-Finding): Refresh nur, wenn der Aufrufer den
            # zuletzt bekannten Token dieser Session vorlegt — wie bei /duplikum/refresh.
            # Ohne die Prüfung wäre der Endpoint ein Token-Automat: dup-user ist frei
            # wählbar, CORS steht auf *, und ein beliebiger abgelaufener Token würde
            # reichen, um sich über den 401-Pfad einen FRISCHEN Token für ein fremdes
            # Konto generieren zu lassen (X-New-Dup-Token). Der Refresh rotiert jetzt nur
            # noch einen Token, den man nachweislich schon besaß.
            sess_known = ((duplikum_sessions.get(refresh_email) or {}).get("token") or "").strip()
            if sess_known and hmac.compare_digest((token or "").strip(), sess_known):
                new_tok = refresh_duplikum_token(refresh_email)
                if new_tok:
                    r = do_request(new_tok)
                    return r.status_code, r.content, r.headers.get("Content-Type", "application/json"), new_tok
        # Duplikum meldet einen ABGELAUFENEN Token als HTTP 200 mit code 1006 —
        # ohne diesen Zweig hat der Proxy nie nachgeholt und das Frontend lief in
        # eine tote Session (06.08.2026 live beobachtet).
        if r.status_code == 200 and refresh_email:
            try:
                body = r.json()
            except Exception:
                body = None
            if isinstance(body, dict) and _dup_is_expired_token(body.get("error"), body.get("code")):
                sess_known = ((duplikum_sessions.get(refresh_email) or {}).get("token") or "").strip()
                if sess_known and hmac.compare_digest((token or "").strip(), sess_known):
                    new_tok = refresh_duplikum_token(refresh_email)
                    if new_tok:
                        r = do_request(new_tok)
                        return r.status_code, r.content, r.headers.get("Content-Type", "application/json"), new_tok
        return r.status_code, r.content, r.headers.get("Content-Type", "application/json"), None

    # ── Nicht-cachebare Calls (Mutationen etc.): direkt durch, wie bisher ──
    if not is_cacheable:
        try:
            status, content, ctype, new_tok = do_full_request()
            # Mapping-Endpoints auch bei 200 loggen: editMapping.php kann mit HTTP 200 aber
            # "updated_count":0 antworten (kein passender old_symbol/old_symbol_master-Treffer)
            # — reiner Status->=400-Check hätte das unsichtbar gemacht (Body sah "erfolgreich"
            # aus, war aber ein No-Op).
            is_mapping_call = "mapping/" in path_norm
            # PROPHOS_DEBUG_DUP=1 (nur lokal setzen): loggt zusätzlich die kompletten
            # getSettings-Antworten — zum Diagnostizieren, welche Mapping-Zeilen Duplikum
            # für einen Slave wirklich zurückgibt (id_master vs. id_group etc.).
            debug_dup = bool(os.environ.get("PROPHOS_DEBUG_DUP"))
            is_settings_read = "getsettings" in path_norm
            if status >= 400 or is_mapping_call or (debug_dup and is_settings_read):
                limit = 6000 if (debug_dup and is_settings_read) else 300
                snippet = (content or b"")[:limit].decode("utf-8", errors="replace")
                icon = "⚠️" if status >= 400 else "ℹ️"
                # flush=True: unter nohup ist stdout block-gepuffert — ohne Flush tauchen
                # die Zeilen erst KB-weise später (oder nie) im Log auf.
                print(f"[duplikum] {icon} {path} → HTTP {status}: {snippet}", flush=True)
                if body_data:
                    print(f"[duplikum]    ↳ Request war: {str(body_data)[:300]}", flush=True)
            resp = Response(content, status=status, content_type=ctype)
            if new_tok: resp.headers["X-New-Dup-Token"] = new_tok
            return resp
        except requests.exceptions.RequestException as e:
            return jsonify({"error": f"Netzwerkfehler: {e}"}), 502
        except Exception as e:
            return jsonify({"error": str(e)}), 500

    # ── Cachebare Lese-Calls: Kurz-Cache + Single-Flight ──
    key = hashlib.md5(
        (path_norm + "|" + token + "|" + json.dumps(body_data or {}, sort_keys=True)
         + "|" + json.dumps(dict(request.args), sort_keys=True)).encode()
    ).hexdigest()
    now = time.time()

    # 1. Schneller Pfad: frischer Cache-Treffer → sofort, ohne Duplikum
    with _dup_cache_lock:
        hit = _dup_cache.get(key)
    if hit and hit[0] > now:
        return Response(hit[2], status=hit[1], content_type=hit[3])

    # 2. Single-Flight: nur EIN Thread pro Key macht den echten Call, der Rest wartet
    with _dup_cache_lock:
        lk = _dup_inflight.get(key)
        if lk is None:
            lk = threading.Lock()
            _dup_inflight[key] = lk
    with lk:
        # Re-Check: ein anderer Thread hat evtl. gerade eben schon gefüllt
        with _dup_cache_lock:
            hit = _dup_cache.get(key)
        if hit and hit[0] > time.time():
            return Response(hit[2], status=hit[1], content_type=hit[3])
        try:
            status, content, ctype, new_tok = do_full_request()
        except requests.exceptions.RequestException as e:
            return jsonify({"error": f"Netzwerkfehler: {e}"}), 502
        except Exception as e:
            return jsonify({"error": str(e)}), 500
        # Nur erfolgreiche Antworten cachen (kein 401/Fehler)
        if status == 200:
            with _dup_cache_lock:
                _dup_cache[key] = (time.time() + DUP_CACHE_TTL, status, content, ctype)
                # opportunistisches Aufräumen abgelaufener Einträge, damit das Dict nicht wächst
                if len(_dup_cache) > 200:
                    tnow = time.time()
                    for k in [k for k, v in _dup_cache.items() if v[0] <= tnow]:
                        _dup_cache.pop(k, None)
        resp = Response(content, status=status, content_type=ctype)
        if new_tok: resp.headers["X-New-Dup-Token"] = new_tok
        return resp

@app.route("/duplikum/refresh", methods=["POST","OPTIONS"])
def duplikum_refresh():
    """Erzwingt einen frischen Duplikum-Token (nächtlicher Auto-Reconnect im Frontend).

    Nutzt die im RAM liegenden Zugangsdaten der bestehenden Session (bzw. die Env-Creds).
    Das Passwort bleibt damit ausschließlich serverseitig — das Frontend braucht es nicht
    zu speichern. Ist keine Session mehr da (z.B. nach einem Backend-Neustart), kommt
    needs_login zurück und das Frontend bittet um einmaliges Neuverbinden.
    """
    if request.method == "OPTIONS":
        return "", 200
    data = request.get_json(silent=True) or {}
    email = (data.get("email") or request.headers.get("dup-user") or "").strip()
    if not email:
        return jsonify({"ok": False, "error": "email fehlt"}), 400

    # SICHERHEIT: Der Aufrufer muss den AKTUELL gültigen Token dieser Session vorlegen.
    # Ohne diese Prüfung wäre der Endpoint ein offener Token-Automat — CORS steht auf "*",
    # d.h. jeder, der die E-Mail kennt, könnte sich sonst einen gültigen Duplikum-Token
    # ausstellen lassen (und damit über den Proxy handeln). Der Refresh rotiert also nur
    # einen Token, den man ohnehin schon besitzt — er vergibt keinen neuen Zugang.
    sess = duplikum_sessions.get(email) or {}
    presented = (request.headers.get("dup-token") or data.get("token") or "").strip()
    known = (sess.get("token") or "").strip()
    if not presented or not known or not hmac.compare_digest(presented, known):
        return jsonify({"ok": False, "error": "Nicht autorisiert"}), 401

    has_creds = bool(sess.get("password")) or \
                bool(DUP_EMAIL and email.lower() == DUP_EMAIL.lower() and DUP_PASSWORD)
    if not has_creds:
        return jsonify({"ok": False, "needs_login": True,
                        "error": "Keine gespeicherten Zugangsdaten — bitte einmal neu verbinden."}), 200
    token = refresh_duplikum_token(email)
    if not token:
        return jsonify({"ok": False, "error": "Token-Refresh fehlgeschlagen"}), 502
    print(f"[duplikum] 🔄 Auto-Reconnect: neuer Token für {email}", flush=True)
    return jsonify({"ok": True, "token": token})

@app.route("/duplikum/disconnect", methods=["POST","OPTIONS"])
def duplikum_disconnect():
    if request.method == "OPTIONS": return "", 200
    data = request.get_json(silent=True) or {}
    email = (data.get("email") or "").strip()
    if email and email in duplikum_sessions:
        del duplikum_sessions[email]
    return jsonify({"ok": True})

# ── Token Refresh ──
def refresh_tsx_token(pair_id, session_obj, max_retries=3):
    """
    Refresh TSX JWT via /api/Auth/validate. Returns True bei Erfolg.
    Probiert bis zu max_retries-mal mit exponentiellem Backoff falls Validate-API selbst fehlschlägt.
    """
    s = mirror_sessions.get(pair_id)
    if not s: return False

    for attempt in range(1, max_retries + 1):
        try:
            r = session_obj.post(f"{TSX_BASE}/api/Auth/validate",
                headers={"Authorization": f"Bearer {s['tsxToken']}", "Content-Type": "application/json"},
                timeout=10)
            # 401 → Token komplett abgelaufen, kein Retry sinnvoll
            if r.status_code == 401:
                log_msg(pair_id, "🔒 Token-Refresh: 401 — Token endgültig abgelaufen, neuer Login nötig")
                s["tokenDead"] = True  # die Worker-Schleifen beenden das Pair damit selbst (15.09.2026)
                return False
            # 5xx → Server-seitig, Retry macht Sinn
            if 500 <= r.status_code < 600:
                if attempt < max_retries:
                    backoff = 2 ** attempt
                    log_msg(pair_id, f"⚠️ Token-Refresh HTTP {r.status_code} (Versuch {attempt}/{max_retries}) — Retry in {backoff}s")
                    time.sleep(backoff)
                    continue
                log_msg(pair_id, f"⚠️ Token-Refresh aufgegeben nach {max_retries} Versuchen")
                return False
            if not r.ok:
                log_msg(pair_id, f"⚠️ Token-Refresh HTTP {r.status_code}: {r.text[:100]}")
                return False
            d = r.json()
            if d.get("success") and d.get("newToken"):
                s["tsxToken"] = d["newToken"]
                s["lastTokenRefresh"] = time.time()
                log_msg(pair_id, "🔄 TSX Token refreshed")
                _sessions_save()
                return True
            log_msg(pair_id, f"⚠️ Token-Refresh: {d.get('errorMessage', d)}")
            return False
        except requests.exceptions.Timeout:
            if attempt < max_retries:
                backoff = 2 ** attempt
                log_msg(pair_id, f"⏱ Token-Refresh Timeout (Versuch {attempt}/{max_retries}) — Retry in {backoff}s")
                time.sleep(backoff)
                continue
            log_msg(pair_id, "⚠️ Token-Refresh Timeout — aufgegeben")
            return False
        except requests.exceptions.ConnectionError as e:
            if attempt < max_retries:
                backoff = 2 ** attempt
                log_msg(pair_id, f"🔌 Token-Refresh Connection error (Versuch {attempt}/{max_retries}) — Retry in {backoff}s")
                time.sleep(backoff)
                continue
            log_msg(pair_id, f"⚠️ Token-Refresh Connection error — aufgegeben")
            return False
        except Exception as e:
            log_msg(pair_id, f"⚠️ Token-Refresh exception: {type(e).__name__}: {str(e)[:80]}")
            return False
    return False

# ── Sessions überleben einen Backend-Neustart (17.09.2026) ──
# Finn: 'Die Updates bitte einfach immer direkt deployen … nicht warten, nichts per Hand
# starten, so wie beim Frontend.' Bisher lebten mirror_sessions NUR im RAM: jedes Update
# hätte scharfe Pläne still entwaffnet — deshalb wartete das Selbst-Update, solange
# irgendein Mirror scharf war, und Chriss' PC hing am 17.09. den ganzen Vormittag auf
# einem zwei Tage alten Backend. Jetzt: aktive Echtzeit-Sessions stehen in einer Sidecar-
# Datei AUSSERHALB des Repos (~/.prophos/mirror-sessions.json, chmod 600 — enthält Token,
# gleiche Vertrauensstufe wie die lokalen Copier-Configs) und werden beim Boot wieder
# scharfgeschaltet, inkl. der laufenden Hedge-Zuordnung (refState), damit eine offene
# Position NICHT ein zweites Mal gehedgt wird. Nur Echtzeit-Sessions: Polling- und
# MT→TSX-Pairs kennen ihre Positionen nur lokal im Thread — für die wartet das Update
# weiter. Auf Railway aus (flüchtiges Dateisystem, dort laufen keine Pairs).
_SIDECAR = os.environ.get("PROPHOS_SIDECAR") or os.path.join(os.path.expanduser("~"), ".prophos", "mirror-sessions.json")  # env nur für die Nachstellung (tools/tsx-stream-test/sim)
_SIDECAR_ON = not (os.environ.get("RAILWAY_GIT_COMMIT_SHA") or os.environ.get("RAILWAY_ENVIRONMENT"))
_sidecar_lock = threading.Lock()
_SIDECAR_KEYS = ("pairId", "tsxToken", "tsxAccountId", "maToken", "maAccountId", "multiplier",
    "targetRiskEur", "pollInterval", "direction", "engine", "oneShot", "opensBlocked", "hadPos",
    "baseInstrument", "symbolMap", "positions", "closedHedges", "refState", "lastTokenRefresh",
    "sltpSync", "notfallFaktor", "notfallPufferPunkte")

def _sessions_save():
    if not _SIDECAR_ON:
        return
    try:
        out = {}
        for pid, ss in list(mirror_sessions.items()):
            if ss.get("active") and ss.get("engine") == "realtime" and ss.get("direction") != "mt_to_tsx":
                out[pid] = {k: ss.get(k) for k in _SIDECAR_KEYS if k in ss}
                out[pid]["savedAt"] = time.time()
        with _sidecar_lock:
            os.makedirs(os.path.dirname(_SIDECAR), exist_ok=True)
            tmp = _SIDECAR + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(out, f)
            try: os.chmod(tmp, 0o600)
            except Exception: pass
            os.replace(tmp, _SIDECAR)
    except Exception as e:
        print(f"[sidecar] ⚠️ Speichern fehlgeschlagen: {type(e).__name__}: {e}")

def _sessions_resume():
    if not _SIDECAR_ON or not os.path.exists(_SIDECAR):
        return
    try:
        with open(_SIDECAR, encoding="utf-8") as f:
            alt = json.load(f)
    except Exception as e:
        print(f"[sidecar] ⚠️ Lesen fehlgeschlagen: {type(e).__name__}: {e}")
        return
    for pid, d in (alt or {}).items():
        # Älter als 20 h: der TSX-Token (24 h) ist ohne Refresh sicher tot — nicht raten.
        if time.time() - float(d.get("savedAt") or 0) > 20 * 3600:
            print(f"[sidecar] ⏭ {pid}: Stand älter als 20 h — nicht wieder scharfgeschaltet")
            continue
        ok, msg = _mirror_session_create(d, resumed=d)
        print(f"[sidecar] ↻ {pid}: {'wieder scharf' if ok else 'NICHT wieder scharf — ' + str(msg)}")
    _sessions_save()

def _mirror_session_create(data, resumed=None):
    pair_id = data.get("pairId")
    engine  = data.get("engine", "polling")
    if not pair_id:
        return False, "pairId fehlt"
    if pair_id in mirror_sessions:
        if mirror_sessions[pair_id].get("active"):
            return True, "Already running"
        # Selbst beendeter Eintrag (Token tot, 15.09.2026) — darf ein Re-Arm nicht blockieren
        mirror_sessions.pop(pair_id, None)
        _hub_kill(mirror_hubs.pop(pair_id, None))

    session = {
        "pairId": pair_id,
        "tsxToken": data.get("tsxToken"),
        "tsxAccountId": data.get("tsxAccountId"),
        "maToken": data.get("maToken"),
        "maAccountId": data.get("maAccountId"),
        "multiplier": float(data.get("multiplier", 0.5)),
        "targetRiskEur": float(data.get("targetRiskEur", 0)),
        "pollInterval": float(data.get("pollInterval", 0.5)),
        "direction": data.get("direction", "tsx_to_mt"),
        # "polling" (Default, bewährt) oder "realtime" (SignalR/GatewayUserTrade, 20.07.2026)
        "engine": engine,
        # EIN PLAN = EIN TRADE (17.09.2026, Finn: 'Trade beendet, Plan steht bei Überprüfen,
        # dann starte ich in Topstep noch einen Trade — und der wird wieder kopiert').
        # Plan-Pairs aus dem Trades-Tab schicken oneShot:true; manuelle Pairs der Mirror-
        # Seite spiegeln weiter dauerhaft. Wirkung nur in der Echtzeit-Engine: sobald nach
        # dem ersten Hedge alles wieder flach ist, werden KEINE neuen Opens mehr gespiegelt
        # (opensBlocked) — die Session lebt weiter, weil der Auto-P&L closedHedges aus ihr
        # liest. Der nächste 'Starten' schaltet frisch scharf.
        "oneShot": bool(data.get("oneShot")),
        "opensBlocked": bool((resumed or {}).get("opensBlocked")),
        "hadPos": bool((resumed or {}).get("hadPos")),
        # NOTFALL-SL/TP (17.09.2026, wie Echo): Master-SL/TP auf TSX werden gekreuzt und
        # mit Puffer HINTER dem Master-Level auf den Hedge gelegt und nachgezogen.
        "sltpSync": bool(data.get("sltpSync")),
        "notfallFaktor": float(data.get("notfallFaktor") or 110.0),
        "notfallPufferPunkte": float(data.get("notfallPufferPunkte") or 100.0),
        # Kontrakt-Basis, auf die sich der Multiplier bezieht ("MNQ" oder "NQ").
        # Fällt der echte Fill auf dem jeweils anderen Kontrakt der Familie, rechnet
        # open_hedge den Faktor 10 automatisch um (Finn handelt mal MNQ, mal NQ —
        # ein stur angewendeter Multiplier wäre dann ein 10x-Fehler im Hedge).
        "baseInstrument": str(data.get("baseInstrument") or "MNQ").upper(),
        "symbolMap": data.get("symbolMap") or {"MNQ": "NAS100", "NQ": "NAS100", "ES": "US500", "MES": "US500"},
        "reverseSymbolMap": {"NAS100": "MNQ", "US500": "MES", "US30": "MYM", "OIL": "CL", "XAUUSD": "GC"},
        "active": True,
        "positions": dict((resumed or {}).get("positions") or {}),
        "closedHedges": list((resumed or {}).get("closedHedges") or []),
        "refState": dict((resumed or {}).get("refState") or {}),
        "log": [],
        "lastTokenRefresh": float((resumed or {}).get("lastTokenRefresh") or time.time()),
    }
    mirror_sessions[pair_id] = session
    if resumed:
        log_msg(pair_id, f"↻ Session nach Backend-Neustart wiederhergestellt (Build {APP_BUILD}) — {len(session['refState'])} laufende Hedge-Zuordnung(en) übernommen", "ok")

    if session["direction"] == "mt_to_tsx":
        worker_fn = run_mirror_mt_to_tsx
    elif engine == "realtime":
        worker_fn = run_mirror_realtime
    else:
        worker_fn = run_mirror

    # Watchdog: falls der Worker durch eine unerwartete Exception crasht, startet er
    # sich automatisch neu — solange SEINE Session (Identität, nicht nur pair_id —
    # Zombie-Bug 21.07.2026) noch aktiv ist.
    def watchdog(pid, fn, sess):
        max_restarts = 5
        restarts = 0
        while mirror_sessions.get(pid) is sess and sess.get("active") and restarts <= max_restarts:
            try:
                fn(pid)
                break  # Worker ist sauber returnt (z.B. weil active=False)
            except Exception as e:
                restarts += 1
                log_msg(pid, f"💥 Worker crashed ({type(e).__name__}: {str(e)[:100]}) — Auto-Restart {restarts}/{max_restarts}")
                time.sleep(2 * restarts)  # kurzer Cooldown
        if restarts > max_restarts:
            log_msg(pid, f"⛔ Worker zu oft gecrasht ({restarts} Restarts) — Pair gestoppt")
            if mirror_sessions.get(pid) is sess:
                sess["active"] = False

    threading.Thread(target=watchdog, args=(pair_id, worker_fn, session), daemon=True).start()
    _sessions_save()
    return True, None

# ── Mirror Control ──
@app.route("/mirror/start", methods=["POST","OPTIONS"])
def mirror_start():
    if request.method == "OPTIONS": return "", 200
    ok, msg = _mirror_session_create(request.get_json() or {})
    if msg == "Already running":
        return jsonify({"ok": True, "msg": msg})
    return jsonify({"ok": True}) if ok else (jsonify({"ok": False, "error": msg}), 400)

@app.route("/mirror/stop", methods=["POST","OPTIONS"])
def mirror_stop():
    if request.method == "OPTIONS": return "", 200
    data = request.get_json()
    pair_id = data.get("pairId")
    if pair_id in mirror_sessions:
        mirror_sessions[pair_id]["active"] = False
        del mirror_sessions[pair_id]
    # Echtzeit-Hub SOFORT trennen (nicht erst nächste Loop-Iteration) — sonst spiegelt
    # die alte SignalR-Verbindung noch bis zu 8s weiter, während schon ein Neustart
    # eine zweite Verbindung aufbaut → doppelte Hedge-Orders.
    _hub_kill(mirror_hubs.pop(pair_id, None))
    _sessions_save()
    return jsonify({"ok": True})

@app.route("/mirror/status", methods=["GET"])
def mirror_status():
    # Wenn ?pairId=... gesetzt: nur diesen einen Pair zurückgeben (Frontend-Format)
    pid = request.args.get("pairId")
    if pid:
        s = mirror_sessions.get(pid)
        if not s:
            return jsonify({"active": False, "log": [], "positions": {}})
        # Frontend erwartet die "log"-Einträge in einem Format mit "timestamp"/"message"/"kind"
        return jsonify({
            "active": s.get("active", False),
            "engine": s.get("engine", "polling"),
            "opensBlocked": bool(s.get("opensBlocked")),
            "log": s.get("log", [])[-200:],  # neue Log-Konsole zeigt die volle Historie scrollbar
            "positions": s.get("positions", {}),
            "closedHedges": s.get("closedHedges", [])[-20:]
        })
    # Ohne Param: alles (für Debug/Übersicht)
    result = {}
    for pid, s in mirror_sessions.items():
        result[pid] = {"active": s["active"], "log": s["log"][-50:], "positions": s["positions"]}
    return jsonify(result)

# ── Mirror-Diagnose: Wer killt den Stream? (08.09.2026) ──
# Der User-Hub schließt seit Juli jede Verbindung als Reaktion aufs Abonnieren —
# kommentarlos (CloseMessage ohne Grund), in beiden Verbindungsmodi, kein Kanal
# bekommt je eine Completion (Mac-Live-Messungen .258–.260). Dieser Lauf beantwortet
# die Streitfrage HART, Stufe für Stufe auf frischen Einzelverbindungen:
#   idle      — nackte Verbindung, KEIN Abo, 12s: stirbt schon die? → Verbindungs-/
#               Sitz-Policy (zweiter Client auf dem Login), kein Abo-Thema
#   accounts / positions / trades — jeweils genau EIN Abo: welcher Kanal triggert?
#   market    — KONTROLLGRUPPE: Market-Hub (hubs/market, SubscribeContractQuotes):
#               läuft der, sind Token, Client-Bibliothek und Netz bewiesen gesund
#               und das Problem ist User-Hub-spezifisch.
# POST /mirror/diagnose {pairId?} kopiert Token/Account aus dem scharfen Pair,
# STOPPT das Pair (saubere Messung ohne parallelen Reconnect-Sturm der Engine;
# Re-Arm danach über den Starten-Knopf) und fährt die Stufen im Hintergrund-Thread;
# GET /mirror/diagnose liefert den Bericht.
_diag_state = {"running": False, "report": None, "started": 0}

def _diag_run_stage(name, hub_url, subs, events, dauer):
    res = {"stufe": name, "verbunden": False, "bestaetigt": [], "events": 0,
           "close_nach_s": None, "logout": False, "fehler": None}
    t0 = [0.0]; closed_at = [None]; ev_count = [0]
    done = threading.Event()
    try:
        h = HubConnectionBuilder()\
            .with_url(hub_url, options={"skip_negotiation": True})\
            .configure_logging(logging.CRITICAL, handler=_SR_NULL_HANDLER)\
            .build()
        def _on_open():
            res["verbunden"] = True
            t0[0] = time.time()
            for method, args in subs:
                def _mk(mname):
                    def _cb(c):
                        res["bestaetigt"].append(mname)
                    return _cb
                try:
                    h.send(method, args, on_invocation=_mk(method))
                except Exception as e:
                    res["fehler"] = f"send {method}: {str(e)[:80]}"
        def _on_close():
            if closed_at[0] is None:
                closed_at[0] = (time.time() - t0[0]) if t0[0] else 0.0
            done.set()
        h.on_open(_on_open)
        h.on_close(_on_close)
        # GatewayLogout getrennt erfassen — das ist der Beweis für Session-Verdrängung
        h.on("GatewayLogout", lambda args: res.__setitem__("logout", True))
        for ev in events:
            h.on(ev, lambda args: ev_count.__setitem__(0, ev_count[0] + 1))
        h.start()
        done.wait(dauer)
        res["events"] = ev_count[0]
        res["close_nach_s"] = round(closed_at[0], 1) if closed_at[0] is not None else None
        _hub_kill(h)
    except Exception as e:
        res["fehler"] = f"{type(e).__name__}: {str(e)[:120]}"
    return res

def _diag_runner(token, acc_id, contract_id):
    user_url = f"{RTC_BASE}/hubs/user?access_token={token}"
    market_url = f"{RTC_BASE}/hubs/market?access_token={token}"
    stufen = []
    stufen.append(_diag_run_stage("idle — Verbindung ohne jedes Abo", user_url, [],
        ["GatewayUserTrade", "GatewayUserPosition"], 12))
    stufen.append(_diag_run_stage("nur SubscribeAccounts", user_url,
        [("SubscribeAccounts", [])], ["GatewayUserAccount"], 8))
    stufen.append(_diag_run_stage("nur SubscribePositions", user_url,
        [("SubscribePositions", [acc_id])], ["GatewayUserPosition"], 8))
    stufen.append(_diag_run_stage("nur SubscribeTrades", user_url,
        [("SubscribeTrades", [acc_id])], ["GatewayUserTrade"], 8))
    stufen.append(_diag_run_stage("KONTROLLE Market-Hub (Quotes)", market_url,
        [("SubscribeContractQuotes", [contract_id])], ["GatewayQuote"], 8))
    _diag_state["report"] = {"fertig": True, "kontrakt": contract_id,
        "stufen": stufen, "ts": time.strftime("%H:%M:%S")}
    _diag_state["running"] = False

@app.route("/mirror/diagnose", methods=["POST", "OPTIONS", "GET"])
def mirror_diagnose():
    if request.method == "OPTIONS":
        return "", 200
    if request.method == "GET":
        return jsonify({"running": _diag_state["running"], "report": _diag_state["report"]})
    if _diag_state["running"]:
        return jsonify({"ok": False, "error": "Diagnose läuft bereits"}), 409
    data = request.get_json(silent=True) or {}
    pair_id = data.get("pairId")
    s = mirror_sessions.get(pair_id) if pair_id else next(iter(mirror_sessions.values()), None)
    if not s:
        return jsonify({"ok": False, "error": "Kein scharfes Pair als Token-Quelle — erst Mirror starten"}), 400
    token = s["tsxToken"]
    acc_id = int(s["tsxAccountId"])
    contract_id = data.get("contractId") or "CON.F.US.MNQ.U26"
    pid = pair_id or next((k for k, v in mirror_sessions.items() if v is s), None)
    if pid:
        mirror_sessions[pid]["active"] = False
        mirror_sessions.pop(pid, None)
        _hub_kill(mirror_hubs.pop(pid, None))
    _diag_state["running"] = True
    _diag_state["report"] = None
    _diag_state["started"] = time.time()
    threading.Thread(target=_diag_runner, args=(token, acc_id, contract_id), daemon=True).start()
    return jsonify({"ok": True, "hinweis": "Diagnose läuft ~50s — Ergebnis per GET /mirror/diagnose; Pair wurde gestoppt, danach neu scharfschalten"})

# ── Mirror Logic (Polling) TSX → MT5 ──
def run_mirror(pair_id):
    s = mirror_sessions.get(pair_id)
    if not s: return

    # Connection Pooling: eine Session pro Mirror Thread
    http = requests.Session()
    http.verify = False

    log_msg(pair_id, f"🚀 Mirror gestartet — TSX → MT5")
    log_msg(pair_id, f"📊 TSX Account: {s.get('tsxAccountId','?')} · MT5 Account: {s.get('maAccountId','?')}")
    target_eur = float(s.get("targetRiskEur", 0))
    multiplier = float(s.get("multiplier", 1.0))
    if target_eur > 0:
        log_msg(pair_id, f"⚙️ Risiko-Mode: dynamisch ({target_eur}€ Ziel pro Trade)")
    else:
        log_msg(pair_id, f"⚙️ Risiko-Mode: Multiplier {multiplier}x")
    log_msg(pair_id, f"⏱ Polling-Intervall: {s.get('pollInterval', 0.5)}s")

    known_positions = {}
    consecutive_errors = 0
    last_heartbeat = time.time()
    HEARTBEAT_INTERVAL = 120  # alle 2 Minuten ein "alles ruhig"-Log
    MAX_BACKOFF = 60  # max 60s zwischen retries

    # Session-IDENTITÄT prüfen (is s), nicht nur active per pair_id — nach Stop+Neustart
    # existiert unter derselben pair_id eine NEUE Session, und der alte Thread würde sonst
    # als Zombie ewig weiterlaufen und parallel spiegeln (Doppel-Orders, 21.07.2026).
    while mirror_sessions.get(pair_id) is s and s.get("active"):
        if _token_tot_beenden(pair_id, s):
            break
        # Proaktiver Token Refresh alle 20 min
        if time.time() - s.get("lastTokenRefresh", 0) > TOKEN_REFRESH_INTERVAL:
            refresh_tsx_token(pair_id, http)

        # Heartbeat — bestätigt periodisch dass der Mirror lebt
        if time.time() - last_heartbeat > HEARTBEAT_INTERVAL:
            n_open = len(known_positions)
            log_msg(pair_id, f"💓 Mirror läuft — {n_open} offene Position{'en' if n_open != 1 else ''}")
            last_heartbeat = time.time()

        try:
            r = http.post(f"{TSX_BASE}/api/Position/searchOpen",
                headers={"Authorization": f"Bearer {s['tsxToken']}", "Content-Type": "application/json"},
                json={"accountId": int(s["tsxAccountId"])},
                timeout=10)

            # 401 → Token abgelaufen → refresh versuchen
            if r.status_code == 401:
                log_msg(pair_id, "🔒 401 Unauthorized — versuche Token Refresh")
                if refresh_tsx_token(pair_id, http):
                    consecutive_errors = 0
                    continue  # sofort retry mit neuem Token
                else:
                    consecutive_errors += 1
                    backoff = min(MAX_BACKOFF, 2 ** min(consecutive_errors, 6))
                    log_msg(pair_id, f"❌ Token Refresh fehlgeschlagen — warte {backoff}s")
                    time.sleep(backoff)
                    continue

            if not r.ok:
                consecutive_errors += 1
                backoff = min(MAX_BACKOFF, 2 ** min(consecutive_errors, 6))
                log_msg(pair_id, f"Poll error: {r.status_code} {r.text[:100]} — warte {backoff}s")
                time.sleep(backoff)
                continue

            # Erfolgreicher Poll → error counter reset
            consecutive_errors = 0

            d = r.json()
            positions = d.get("positions", d.get("data", []))
            current = {str(p.get("id", p.get("positionId", ""))): p for p in positions}

            for pid, pos in current.items():
                if pid not in known_positions:
                    raw_side = pos.get("side", pos.get("action", ""))
                    raw_type = pos.get("type", 0)
                    if raw_type == 1 or raw_side in ("Buy", "buy", "BUY", "Long", 0, "0"):
                        side = "Buy"
                    else:
                        side = "Sell"
                    contract = pos.get("contractId", "")
                    qty = int(pos.get("size", pos.get("quantity", 1)))
                    tsx_risk = float(pos.get("initialRisk", pos.get("risk", 0)) or 0)
                    log_msg(pair_id, f"🆕 TSX Position erkannt: {side} {qty}× {contract}" + (f" · Risk ${tsx_risk}" if tsx_risk > 0 else ""))
                    log_msg(pair_id, f"➡️ Spiegle nach MT5…")
                    open_hedge(pair_id, pid, side, contract, qty, tsx_risk)
                    last_heartbeat = time.time()  # Trade ist Aktivität → Heartbeat reset

            for pid in list(known_positions.keys()):
                if pid not in current:
                    log_msg(pair_id, f"🔚 TSX Position geschlossen: {pid[:12]}…")
                    log_msg(pair_id, f"➡️ Schließe Hedge auf MT5…")
                    close_hedge(pair_id, pid)
                    last_heartbeat = time.time()

            known_positions = current

        except requests.exceptions.Timeout:
            consecutive_errors += 1
            backoff = min(MAX_BACKOFF, 2 ** min(consecutive_errors, 6))
            log_msg(pair_id, f"⏱ Timeout — warte {backoff}s")
            time.sleep(backoff)
            continue
        except requests.exceptions.ConnectionError as e:
            consecutive_errors += 1
            backoff = min(MAX_BACKOFF, 2 ** min(consecutive_errors, 6))
            log_msg(pair_id, f"🔌 Connection error: {str(e)[:80]} — warte {backoff}s")
            time.sleep(backoff)
            continue
        except (requests.exceptions.JSONDecodeError, ValueError, KeyError, TypeError) as e:
            # API hat unerwartetes/partielles JSON geschickt (z.B. während Maintenance)
            consecutive_errors += 1
            backoff = min(MAX_BACKOFF, 2 ** min(consecutive_errors, 6))
            log_msg(pair_id, f"📦 Bad data from TSX: {type(e).__name__} {str(e)[:80]} — warte {backoff}s")
            time.sleep(backoff)
            continue
        except Exception as e:
            # Wirklich unerwartete Exception — niemals den Worker sterben lassen
            consecutive_errors += 1
            backoff = min(MAX_BACKOFF, 2 ** min(consecutive_errors, 6))
            log_msg(pair_id, f"⚠️ Unerwarteter Fehler: {type(e).__name__}: {str(e)[:120]} — warte {backoff}s")
            time.sleep(backoff)
            continue

        time.sleep(s.get("pollInterval", 0.5))

    http.close()
    log_msg(pair_id, "Mirror gestoppt")

# ── TSX → MT5 Mirror, Echtzeit (SignalR statt Polling, 20.07.2026) ──
# Ersetzt das 0,5s-Poll-Intervall durch den ProjectX User-Hub (GatewayUserTrade-Event
# pro Fill statt Snapshot-Diff) — behebt die Over-/Undershoot-Probleme aus dem alten
# Poll-Modell (zwischen zwei Polls konnten schon mehrere Fills passiert sein).
# Bewusst NEU statt Ersatz für run_mirror(): Alt bleibt als Fallback/Vergleich nutzbar,
# `engine` in /mirror/start wählt den Worker (Default weiter "polling").
#
# Positions-Tracking läuft über Netto-Menge pro Contract aus dem Trade-Stream selbst
# (nicht über ein GatewayUserPosition "geschlossen"-Signal — dessen genaue Semantik ist
# in der ProjectX-Doku nicht dokumentiert, das selbst berechnete Netto ist dagegen aus
# klar dokumentierten GatewayUserTrade-Feldern (side, size) ableitbar und damit sicherer).
# Reconciliation läuft nur als Log-Warnung (kein Auto-Fix) — bewusst konservativ für die
# erste Version mit echtem Geld; Auto-Heal kann nachgezogen werden sobald das im Alltag
# eine Weile sauber gelaufen ist.
# 1s: seit die Reconciliation selbst heilt (Auto-Übernahme/Auto-Close statt Warnung),
# ist sie das eigentliche Arbeitstier solange der Stream zickt — 60 searchOpen/min
# bleibt klar unter dem dokumentierten Rate-Limit (200 Req/60s, History ausgenommen).
RT_RECONCILE_INTERVAL = 1

def run_mirror_realtime(pair_id):
    s = mirror_sessions.get(pair_id)
    if not s: return

    http = requests.Session()
    http.verify = False

    log_msg(pair_id, "🚀 Mirror gestartet — TSX → MT5 (Echtzeit/SignalR)")
    log_msg(pair_id, f"📊 TSX Account: {s.get('tsxAccountId','?')} · MT5 Account: {s.get('maAccountId','?')}")
    target_eur = float(s.get("targetRiskEur", 0))
    multiplier = float(s.get("multiplier", 1.0))
    if target_eur > 0:
        log_msg(pair_id, f"⚙️ Risiko-Mode: dynamisch ({target_eur}€ Ziel pro Trade)")
    else:
        log_msg(pair_id, f"⚙️ Risiko-Mode: Multiplier {multiplier}x")

    # Netto-Menge pro Contract (signed: + = Long, - = Short) + Referenz-ID für close_hedge
    net = {}           # contractId -> signed qty
    ref = {}           # contractId -> hedge reference id (für s["positions"] / close_hedge)
    seen_trades = {}   # trade-id -> ts. Dedup gegen doppelt zugestellte Events (z.B. nach
                       # Reconnect oder falls serverseitig je doppelt abonniert) — ein doppelt
                       # verarbeiteter Fill würde net verfälschen und falsche Hedges auslösen.
    for _c, _st in (s.get("refState") or {}).items():
        # Wiederaufnahme nach Backend-Neustart: die laufende Hedge-Zuordnung übernehmen,
        # sonst sähe der Abgleich die offene TSX-Position als 'ohne Hedge' und eröffnete
        # einen ZWEITEN. Ist die TSX-Position inzwischen zu, schließt der Abgleich den
        # Hedge über den normalen Phantom-Pfad.
        if _st.get("rid") in (s.get("positions") or {}):
            net[_c] = int(_st.get("net") or 0)
            ref[_c] = _st["rid"]
    sub_lock = threading.Lock()
    # pos_lock serialisiert ALLE net/ref-Mutationen inkl. Hedge-Auslösung — Event-Thread
    # (on_trade) und Worker-Thread (Baseline/Heal) dürfen nie gleichzeitig dieselbe
    # Position adoptieren, sonst öffnen beide einen Hedge (Race → Doppel-Order).
    pos_lock = threading.Lock()
    first_event_logged = [False]
    reconnects = [0]
    opened_at = {}         # contractId -> Zeitpunkt der lokalen Übernahme. Ersetzt den alten
                           # 2-Pass-Phantom-Zähler: statt zwei Abgleich-Runden zu warten
                           # (kostete beim Schließen 4-6s, Finns Kritik 21.07.), reicht EIN
                           # Pass, solange die Position älter ist als der REST-Snapshot sein
                           # kann (2,5s-Guard gegen das Race "Event eröffnet Position, während
                           # der gerade gezogene ältere Snapshot sie noch nicht kennt").
    last_rebuild = [0]     # Cap gegen Rebuild-Loops (erster Heal darf sofort)
    rebuild_count = [0]    # nach 3 erfolglosen Neuaufbauten: nur noch alle 5 min versuchen
    stream_events = [0]    # empfangene GatewayUserTrade-Events — Diagnose: Stream lebt vs. tot
    conn_mode = ["direct"] # "direct" (skip_negotiation, wie ProjectX-JS-Doku) | "negotiate"
                           # (Standard-SignalR-Handshake). Liefert der Direktmodus nachweislich
                           # keine Events (Heal nötig, 0 Events), wird beim Neuaufbau auf
                           # Negotiation gewechselt — Verdacht: Load-Balancer hinter
                           # rtc.topstepx.com braucht das Handshake für korrektes Routing.
    closes_noevent = [0]   # Server-Closes seit dem letzten empfangenen Event (08.09.2026):
                           # Live vom Mac gemessen: Server schickt ~2s nach JEDEM Abonnieren
                           # eine CloseMessage ohne Grund, Library reconnectet, endlos —
                           # 44+ Reconnects, 0 Events, und der alte Modus-Flip hing am Heal,
                           # der bei flachem Konto nie feuert. Dieser Zähler erkennt den
                           # Sturm auch OHNE offene Position.
    flip_tries = [0]       # Modus-Wechsel wegen Close-Sturm (nach 4 vergeblichen: parken)
    stream_parked = [0]    # 0 = Stream aktiv; sonst Unix-Zeit, bis zu der der Stream pausiert
                           # (hub gestoppt statt 2s-Dauerhämmern — die Reconnect-Stürme haben
                           # am 21.07. serverseitig HTTP 429 provoziert; Kopien laufen über
                           # den 1s-Abgleich weiter)
    baseline_done = [False]  # Connect-Baseline nur einmal (17.09.2026, s. do_subscribe)
    had_pos = [bool(s.get("hadPos"))]  # oneShot: gab es in dieser Session schon einen Hedge?
    snapshot = [0.0, []]     # letzter searchOpen-Stand des Abgleichs (für den SL/TP-Thread)
    state_sig = [""]         # zuletzt gesicherte Hedge-Zuordnung (Sidecar)
    blocked_logged = set()   # oneShot: pro Contract nur EINE 'nicht gespiegelt'-Zeile
    rec_warn = [0.0]         # letzter 'Abgleich blind'-Hinweis (Drossel 30s)
    last_pos_evt = [0.0]   # Zeitpunkt des letzten GatewayUserPosition-Events (08.09.2026):
                           # solange Positions-Events fließen (<30s alt), sind SIE die
                           # Wahrheitsquelle und der Trade-Event-Pfad mutiert net NICHT mehr —
                           # Positions-Events tragen ABSOLUTE Größen, Trade-Events Deltas;
                           # beide gleichzeitig zu verrechnen würde Fills doppelt zählen
                           # (Adoption per Positions-Event + nachlaufendes Fill-Event).

    # SignalR-interne Logs (INFO+) in die Pair-Konsole spiegeln — wenn der SERVER die
    # Verbindung aktiv trennt, nennt er den Grund in einer Close-Message, die die Library
    # nur auf INFO-Level loggt. Ohne diese Bridge flogen wir bei Verbindungsproblemen
    # blind (Reconnect-Bursts beim Live-Test 21.07.2026, Ursache unsichtbar).
    class _SrLogBridge(logging.Handler):
        def emit(self, record):
            try:
                if not session_alive():
                    return
                m = record.getMessage()
                if not m:
                    return
                log_msg(pair_id, f"📶 SignalR: {str(m)[:180]}", "warn" if record.levelno >= logging.WARNING else "info")
            except Exception:
                pass
    _sr_logger = logging.getLogger("SignalRCoreClient")
    _sr_bridge = _SrLogBridge(level=logging.INFO)
    _sr_logger.addHandler(_sr_bridge)

    # WICHTIG (Lesson vom 21.07.2026, Zombie-Thread-Bug): Session-IDENTITÄT prüfen, nicht
    # nur active-Flag per pair_id. Nach Stop+Neustart existiert unter derselben pair_id eine
    # NEUE Session — der alte Thread muss sich selbst als überholt erkennen und beenden,
    # sonst spiegeln zwei Verbindungen parallel (Doppel-Orders).
    def session_alive():
        return mirror_sessions.get(pair_id) is s and s.get("active")

    def hub_is_current(h):
        return mirror_hubs.get(pair_id) is h

    def pruef_one_shot():
        """Nach jedem Close (und pro Schleifenrunde) aufgerufen: war schon ein Hedge offen
        und ist jetzt alles flach, sperrt ein oneShot-Pair neue Opens. Bewusst KEIN Stop:
        Closes/closedHedges/Status bleiben, und am Kopierpfad selbst ändert sich nichts."""
        if s.get("oneShot") and had_pos[0] and not ref and not s.get("opensBlocked"):
            s["opensBlocked"] = True
            _sessions_save()
            log_msg(pair_id, "⏸️ Trade beendet — ein Plan, ein Trade: weitere TSX-Trades auf diesem Account werden NICHT mehr gespiegelt, bis der nächste Plan gestartet wird.", "ok")

    def open_gesperrt(contract):
        if not s.get("opensBlocked"):
            return False
        if contract not in blocked_logged:
            blocked_logged.add(contract)
            log_msg(pair_id, f"⏸️ Neuer TSX-Trade auf {contract} NICHT gespiegelt — der Plan dieses Pairs ist beendet (Überprüfen). Nächsten Plan starten, dann wird wieder gespiegelt.", "warn")
        return True

    def fetch_risk_for_contract(contract_id):
        """Best-effort: initialRisk für eine gerade neu erkannte Position nachladen,
        damit der dynamische Risiko-Modus (targetRiskEur) auch im Echtzeit-Pfad
        funktioniert. Schlägt der Call fehl, fällt open_hedge auf Multiplier zurück."""
        try:
            r = http.post(f"{TSX_BASE}/api/Position/searchOpen",
                headers={"Authorization": f"Bearer {s['tsxToken']}", "Content-Type": "application/json"},
                json={"accountId": int(s["tsxAccountId"])}, timeout=8)
            if not r.ok: return 0
            positions = r.json().get("positions", r.json().get("data", []))
            for p in positions:
                if p.get("contractId") == contract_id:
                    return float(p.get("initialRisk", p.get("risk", 0)) or 0)
        except Exception:
            pass
        return 0

    def is_dup_trade(tid):
        if tid is None: return False
        key = str(tid)
        if key in seen_trades: return True
        seen_trades[key] = time.time()
        if len(seen_trades) > 2000:
            for k in sorted(seen_trades, key=seen_trades.get)[:1000]:
                seen_trades.pop(k, None)
        return False

    def on_trade(h, args):
        try:
            if not session_alive() or not hub_is_current(h):
                return  # überholte Verbindung/Session — nichts mehr auslösen
            # Defensive: Event-Payload kann [tradeObj] oder [accountId, tradeObj] sein
            data = None
            if args and isinstance(args[0], dict): data = args[0]
            elif args and len(args) > 1 and isinstance(args[1], dict): data = args[1]
            if data is None: return
            stream_events[0] += 1
            closes_noevent[0] = 0  # Stream liefert — kein Sturm (mehr)
            if time.time() - last_pos_evt[0] < 30:
                return  # Positions-Stream lebt und ist die Wahrheitsquelle (absolute Größen) —
                        # Trade-Deltas zusätzlich zu verrechnen würde doppelt zählen
            if not first_event_logged[0]:
                first_event_logged[0] = True
                log_msg(pair_id, f"📡 Erstes Trade-Event empfangen: {json.dumps(data)[:220]}")
            evt_acc = data.get("accountId")
            if evt_acc is not None and str(evt_acc) != str(s.get("tsxAccountId")):
                return  # Event für einen anderen Account auf derselben Connection
            if is_dup_trade(data.get("id")):
                return  # exakt dieses Trade-Event wurde schon verarbeitet
            contract = data.get("contractId", "")
            raw_side = data.get("side", 0)
            size = int(data.get("size", 0) or 0)
            if not contract or size <= 0:
                return
            signed = size if raw_side in (0, "0", "Buy", "buy", "BUY", "Long", "long", "B") else -size

            with pos_lock:
                prev = net.get(contract, 0)
                new = prev + signed
                net[contract] = new

                if prev == 0 and new != 0 and open_gesperrt(contract):
                    net[contract] = 0   # nicht tracken — sonst sähe der spätere Close wie unser Hedge aus
                elif prev == 0 and new != 0:
                    # Neue Position
                    had_pos[0] = True
                    rid = ref.get(contract) or f"rt-{contract}-{uuid.uuid4().hex[:8]}"
                    ref[contract] = rid
                    opened_at[contract] = time.time()
                    side_label = "Buy" if new > 0 else "Sell"
                    log_msg(pair_id, f"🆕 TSX Fill erkannt (Echtzeit): {side_label} {abs(new)}× {contract}")
                    risk = fetch_risk_for_contract(contract) if target_eur > 0 else 0
                    log_msg(pair_id, "➡️ Spiegle nach MT5…")
                    open_hedge(pair_id, rid, 0 if new > 0 else 1, contract, abs(new), risk)
                elif prev != 0 and new == 0:
                    # Position komplett geschlossen
                    rid = ref.pop(contract, None)
                    opened_at.pop(contract, None)
                    log_msg(pair_id, f"🔚 TSX Position geschlossen (Echtzeit): {contract}")
                    if rid:
                        log_msg(pair_id, "➡️ Schließe Hedge auf MT5…")
                        close_hedge(pair_id, rid)
                    pruef_one_shot()
                elif prev != 0 and new != 0 and (prev > 0) != (new > 0):
                    # Durchgerutscht (Long→Short direkt ohne 0-Zwischenstand) — alten Hedge zu,
                    # neuen auf. Seltener Fall (ein einzelner großer Gegen-Trade).
                    rid_old = ref.pop(contract, None)
                    if rid_old:
                        log_msg(pair_id, f"🔁 TSX Position durch Gegen-Trade gedreht: {contract} — schließe alten Hedge…")
                        close_hedge(pair_id, rid_old)
                    rid_new = f"rt-{contract}-{uuid.uuid4().hex[:8]}"
                    ref[contract] = rid_new
                    opened_at[contract] = time.time()
                    risk = fetch_risk_for_contract(contract) if target_eur > 0 else 0
                    log_msg(pair_id, "➡️ Öffne gedrehten Hedge auf MT5…")
                    open_hedge(pair_id, rid_new, 0 if new > 0 else 1, contract, abs(new), risk)
                elif prev != 0 and new != 0:
                    # Größe innerhalb einer offenen Position geändert (Nachkauf/Teilverkauf) —
                    # wie im alten Poll-Modell (das reagiert auch nur auf neu/weg, nicht auf
                    # Größenänderung) wird das hier nur geloggt, nicht automatisch nachjustiert.
                    log_msg(pair_id, f"ℹ️ Positionsgröße geändert: {contract} {prev}→{new} (Hedge-Größe bleibt wie beim Opening — nicht automatisch angepasst)")
        except Exception as e:
            log_msg(pair_id, f"⚠️ Fehler beim Verarbeiten eines Trade-Events: {type(e).__name__}: {str(e)[:120]}")

    def on_position(h, args):
        """GatewayUserPosition als Push-Quelle (08.09.2026, Finns '<0,5s'-Vorgabe):
        Positions-Events tragen die ABSOLUTE Ist-Größe (size, type 1=Long/2=Short;
        size 0 = Position zu) — genau die Information, die der 1s-Abgleich bisher
        per REST zusammensammeln musste. Der Handler spielt bewusst NUR die Rolle
        des Abgleichs: übernehmen / schließen / drehen über dieselben Locks und
        Refs wie Trade-Pfad und Heal — kommt für denselben Übergang zusätzlich ein
        Trade-Event, findet es den Zustand schon korrekt vor und tut nichts (bzw.
        ist per last_pos_evt ganz abgeschaltet, solange Positions-Events fließen).
        Zweiter Grund für diesen Kanal: der Server killt seit Juli jede Verbindung
        als Reaktion auf SubscribeTrades — ob POSITIONS-Abos durchgelassen werden,
        entscheidet sich hiermit; wenn ja, ist der Sub-Sekunden-Pfad offen, auch
        ohne Trade-Events."""
        try:
            if not session_alive() or not hub_is_current(h):
                return
            data = None
            if args and isinstance(args[0], dict): data = args[0]
            elif args and len(args) > 1 and isinstance(args[1], dict): data = args[1]
            if data is None: return
            if "contractId" not in data and isinstance(data.get("data"), dict):
                data = data["data"]  # Payload kommt je nach Gateway-Version auch verschachtelt
            evt_acc = data.get("accountId")
            if evt_acc is not None and str(evt_acc) != str(s.get("tsxAccountId")):
                return
            contract = data.get("contractId", "")
            if not contract:
                return
            stream_events[0] += 1
            closes_noevent[0] = 0
            last_pos_evt[0] = time.time()
            if not first_event_logged[0]:
                first_event_logged[0] = True
                log_msg(pair_id, f"📡 Erstes Positions-Event empfangen: {json.dumps(data)[:220]}")
            size = int(float(data.get("size", 0) or 0))
            ptype = data.get("type", 0)
            is_buy = ptype in (1, "1", "Long", "long", "Buy", "buy")
            with pos_lock:
                tracked = net.get(contract, 0)
                if size == 0 and tracked != 0:
                    rid = ref.pop(contract, None)
                    net[contract] = 0
                    opened_at.pop(contract, None)
                    log_msg(pair_id, f"🔚 TSX Position zu (Positions-Event): {contract}")
                    if rid:
                        log_msg(pair_id, "➡️ Schließe Hedge auf MT5…")
                        close_hedge(pair_id, rid)
                    pruef_one_shot()
                elif size > 0 and tracked == 0 and contract not in ref and open_gesperrt(contract):
                    pass
                elif size > 0 and tracked == 0 and contract not in ref:
                    had_pos[0] = True
                    net[contract] = size if is_buy else -size
                    rid = f"rt-{contract}-{uuid.uuid4().hex[:8]}"
                    ref[contract] = rid
                    opened_at[contract] = time.time()
                    log_msg(pair_id, f"🆕 TSX Position offen (Positions-Event): {'Buy' if is_buy else 'Sell'} {size}× {contract}")
                    risk = float(data.get("initialRisk", 0) or 0) or (fetch_risk_for_contract(contract) if target_eur > 0 else 0)
                    log_msg(pair_id, "➡️ Spiegle nach MT5…")
                    open_hedge(pair_id, rid, 0 if is_buy else 1, contract, size, risk)
                elif size > 0 and tracked != 0:
                    signed = size if is_buy else -size
                    if (signed > 0) != (tracked > 0):
                        rid_old = ref.pop(contract, None)
                        if rid_old:
                            log_msg(pair_id, f"🔁 TSX Position gedreht (Positions-Event): {contract} — schließe alten Hedge…")
                            close_hedge(pair_id, rid_old)
                        rid_new = f"rt-{contract}-{uuid.uuid4().hex[:8]}"
                        ref[contract] = rid_new
                        opened_at[contract] = time.time()
                        net[contract] = signed
                        risk = fetch_risk_for_contract(contract) if target_eur > 0 else 0
                        log_msg(pair_id, "➡️ Öffne gedrehten Hedge auf MT5…")
                        open_hedge(pair_id, rid_new, 0 if signed > 0 else 1, contract, abs(signed), risk)
                    elif signed != tracked:
                        # Absolute Größe ist autoritativ — net syncen, Hedge-Policy wie im
                        # Trade-Pfad: Größenänderung wird geloggt, nicht nachjustiert.
                        net[contract] = signed
                        log_msg(pair_id, f"ℹ️ Positionsgröße geändert (Positions-Event): {contract} {tracked}→{signed} (Hedge bleibt wie beim Opening)")
        except Exception as e:
            log_msg(pair_id, f"⚠️ Fehler beim Verarbeiten eines Positions-Events: {type(e).__name__}: {str(e)[:120]}")

    def sync_baseline(heal=False, snapshot=None):
        """Bereits offene TSX-Positionen (offen vor Verbindungsaufbau, oder während eines
        Reconnects/Stream-Ausfalls verpasst) per REST übernehmen — der Event-Stream liefert
        nur NEUE Fills. Läuft bei jedem (Re-)Connect UND als Heal aus der Reconciliation;
        bereits getrackte Contracts werden übersprungen. heal=True ändert nur die Log-Texte.
        snapshot: bereits vorliegende searchOpen-Positionsliste (08.09.2026) — der Heal-Pfad
        hatte die Liste 300ms vorher selbst gezogen und sync_baseline zog sie NOCHMAL;
        auf Finns '<0,5s'-Jagd zählt jeder gesparte Roundtrip."""
        try:
            if snapshot is not None:
                positions = snapshot
            else:
                r = http.post(f"{TSX_BASE}/api/Position/searchOpen",
                    headers={"Authorization": f"Bearer {s['tsxToken']}", "Content-Type": "application/json"},
                    json={"accountId": int(s["tsxAccountId"])}, timeout=10)
                if not r.ok:
                    log_msg(pair_id, f"⚠️ Baseline-Sync: HTTP {r.status_code} — {r.text[:80]}", "warn")
                    return 0
                positions = r.json().get("positions", r.json().get("data", []))
            taken = 0
            with pos_lock:
                for pos in positions:
                    contract = pos.get("contractId", "")
                    if not contract or contract in ref: continue
                    raw_side = pos.get("side", pos.get("action", ""))
                    raw_type = pos.get("type", 0)
                    is_buy = raw_type == 1 or raw_side in (0, "0", "Buy", "buy", "BUY", "Long")
                    qty = int(pos.get("size", pos.get("quantity", 1)) or 0)
                    if qty <= 0: continue
                    if open_gesperrt(contract): continue
                    had_pos[0] = True
                    tsx_risk = float(pos.get("initialRisk", pos.get("risk", 0)) or 0)
                    net[contract] = qty if is_buy else -qty
                    rid = f"rt-{contract}-{uuid.uuid4().hex[:8]}"
                    ref[contract] = rid
                    opened_at[contract] = time.time()
                    taken += 1
                    if heal:
                        log_msg(pair_id, f"🛟 Stream-Lücke — übernehme TSX-Position per REST: {'Buy' if is_buy else 'Sell'} {qty}× {contract}", "warn")
                    else:
                        log_msg(pair_id, f"🆕 Bereits offene TSX-Position übernommen: {'Buy' if is_buy else 'Sell'} {qty}× {contract}")
                    log_msg(pair_id, "➡️ Spiegle nach MT5…")
                    open_hedge(pair_id, rid, 0 if is_buy else 1, contract, qty, tsx_risk)
            # Auch Stille diagnostizierbar machen — beim letzten Mal war unklar, ob der
            # Baseline-Sync überhaupt gelaufen ist. (Nur beim Connect-Sync, Heals sind eh laut.)
            if not heal:
                if not positions:
                    log_msg(pair_id, "📊 Baseline-Sync: keine offenen TSX-Positionen")
                elif taken == 0:
                    log_msg(pair_id, "📊 Baseline-Sync: alle offenen Positionen bereits getrackt")
            return taken
        except Exception as e:
            log_msg(pair_id, f"⚠️ Baseline-Sync fehlgeschlagen: {type(e).__name__}: {str(e)[:100]}", "warn")
            return 0

    def do_subscribe(h):
        if not session_alive() or not hub_is_current(h):
            return  # überholte Verbindung soll weder abonnieren noch Baseline-Hedges auslösen
        with sub_lock:
            if getattr(h, "_pph_subscribed", False):
                return  # schon abonniert auf DIESER Verbindung — ein zweites SubscribeTrades
                        # würde jedes Event doppelt zustellen (→ falsche net-Stände)
            try:
                # ALLE VIER Kanäle abonnieren (08.09.2026): Das offizielle ProjectX-Beispiel
                # abonniert immer Accounts+Orders+Positions+Trades zusammen — wir schickten
                # seit Juli nur SubscribeTrades, und der Server schloss JEDE Verbindung als
                # Reaktion darauf (beide Verbindungsmodi, nie eine Completion). Ob er
                # Teil-Abos als ungültigen Client wertet oder nur den Trades-Kanal sperrt:
                # die Einzel-Bestätigungen unten machen es erstmals sichtbar. Positions ist
                # dabei der wichtigste Kanal — on_position trägt seit heute den Sub-Sekunden-
                # Pfad auch ohne Trade-Events.
                # on_invocation: Server-Completion abwarten — nur so wissen wir sicher,
                # ob ein Abonnement akzeptiert wurde (Ablehnung käme als Error-Completion
                # und landet über on_error in der Konsole).
                acc_id = int(s["tsxAccountId"])
                h._pph_sub_ok = set()
                def _mk_conf(name, hh=h):
                    def _cb(completion):
                        if hub_is_current(hh):
                            hh._pph_sub_ok.add(name)
                            log_msg(pair_id, f"✅ {name} vom Server bestätigt")
                    return _cb
                h.send("SubscribeAccounts", [], on_invocation=_mk_conf("SubscribeAccounts"))
                h.send("SubscribeOrders", [acc_id], on_invocation=_mk_conf("SubscribeOrders"))
                h.send("SubscribePositions", [acc_id], on_invocation=_mk_conf("SubscribePositions"))
                h.send("SubscribeTrades", [acc_id], on_invocation=_mk_conf("SubscribeTrades"))
                h._pph_subscribed = True
                # 3s-Wächter (08.09.2026): Beim Mac-Live-Test kam NIE eine Bestätigung —
                # der Server schloss die Verbindung, STATT das Abo abzuschließen. Mit den
                # Einzel-Bestätigungen zeigt der Wächter jetzt, WELCHER Kanal hängt.
                def _sub_check(hh=h):
                    if not (session_alive() and hub_is_current(hh)):
                        return
                    fehlend = {"SubscribeAccounts", "SubscribeOrders", "SubscribePositions", "SubscribeTrades"} - getattr(hh, "_pph_sub_ok", set())
                    if fehlend:
                        log_msg(pair_id, f"⚠️ Ohne Server-Bestätigung nach 3s: {', '.join(sorted(fehlend))} — der Close ist vermutlich die Server-Reaktion darauf", "warn")
                _t = threading.Timer(3.0, _sub_check)
                _t.daemon = True
                _t.start()
            except Exception as e:
                log_msg(pair_id, f"⚠️ Subscribe fehlgeschlagen: {type(e).__name__}: {str(e)[:100]}", "warn")
                return
        log_msg(pair_id, "🔌 Verbunden & abonniert: Accounts, Orders, Positions, Trades (User Hub)")
        # Baseline nur beim ERSTEN Connect (17.09.2026): do_subscribe läuft im Empfangs-
        # Thread der Library; im Close-Sturm (Reconnect alle ~2s) zog jeder Reconnect hier
        # ein eigenes searchOpen — zusätzlich zum 1s-Abgleich, der dieselbe Übernahme
        # ohnehin binnen 1s macht. Das verdoppelte die Request-Last Richtung Rate-Limit
        # (200/60s) und blockierte den Empfangs-Thread bis zu 10s.
        if not baseline_done[0]:
            baseline_done[0] = True
            sync_baseline()

    def on_hub_reopen(h):
        # Nach einem Reconnect ist es serverseitig eine NEUE Verbindung — Subscription
        # ist weg und muss neu angemeldet werden.
        with sub_lock:
            h._pph_subscribed = False
        reconnects[0] += 1
        # Sturm-Zähler HIER, nicht in on_hub_close (08.09.2026, zweiter Mac-Live-Test):
        # signalrcore feuert on_close bei Auto-Reconnects NIE (on_socket_close biegt
        # vorher in handle_reconnect ab) — der Zähler blieb 0 und Flip/Parken griffen
        # nicht. Jeder Reconnect beweist aber einen vorausgegangenen Close.
        if hub_is_current(h) and session_alive():
            closes_noevent[0] += 1
        log_msg(pair_id, f"🔁 Stream-Reconnect #{reconnects[0]}", "warn")
        do_subscribe(h)

    def on_hub_close(h):
        with sub_lock:
            h._pph_subscribed = False
        if session_alive() and hub_is_current(h):
            closes_noevent[0] += 1
            log_msg(pair_id, "🔌 Verbindung getrennt — automatischer Reconnect läuft…", "warn")

    def build_hub(token):
        # Callbacks werden fest an DIESES Hub-Objekt gebunden (Parameter h, nicht die äußere
        # hub-Variable!) — sonst greifen die Callbacks einer alten Verbindung nach einem
        # Token-Refresh auf die NEUE Verbindung zu und der Identitäts-Check läuft ins Leere.
        use_negotiate = conn_mode[0] == "negotiate"
        log_msg(pair_id, f"🔧 Verbindungsmodus: {'Negotiation-Handshake' if use_negotiate else 'Direkt (skip negotiation)'}")
        h = HubConnectionBuilder()\
            .with_url(f"{RTC_BASE}/hubs/user?access_token={token}", options={"skip_negotiation": not use_negotiate}) \
            .configure_logging(logging.INFO, handler=_sr_bridge) \
            .with_automatic_reconnect({
                "type": "interval",
                "keep_alive_interval": 10,
                "intervals": [1, 2, 5, 10, 15, 30, 60]
            }).build()
        h.on_open(lambda: do_subscribe(h))
        h.on_reconnect(lambda: on_hub_reopen(h))
        h.on_close(lambda: on_hub_close(h))
        # Completion-Errors kommen als CompletionMessage-Objekt — .error extrahieren,
        # sonst steht nur der Objektname im Log statt der Server-Begründung.
        h.on_error(lambda e: log_msg(pair_id, f"⚠️ Hub-Fehler: {str(getattr(e, 'error', None) or e)[:150]}", "warn"))
        h.on("GatewayUserTrade", lambda args: on_trade(h, args))
        h.on("GatewayUserPosition", lambda args: on_position(h, args))
        # GatewayLogout (08.09.2026): Der Server schickt dieses Event laut project-x-py
        # (Issue #100) unmittelbar VOR einem bewussten Session-Abbruch — genau unser
        # Muster (leere CloseMessage im 2s-Takt). Ohne Handler blieb es unsichtbar und
        # der Close wirkte grundlos. Jetzt beweist es Session-Verdrängung SCHWARZ AUF
        # WEISS: ein zweiter Consumer desselben ProjectX-Users (anderes Backend, zweiter
        # Prophos-Tab mit eigenem loginKey, TopstepX-Plattform) hat uns hinausgeworfen.
        h.on("GatewayLogout", lambda args: log_msg(pair_id, f"🚪 SERVER-LOGOUT — die TSX-Session wurde serverseitig beendet (anderer Login/Consumer auf demselben ProjectX-User). Nutzlast: {json.dumps(args)[:150]}", "err"))
        return h

    def rebuild_connection(reason, flip_mode=False):
        # Registrierung ZUERST auf die neue Verbindung umbiegen, dann alte stoppen —
        # so erkennen sich alle Callbacks der alten sofort als überholt.
        nonlocal hub
        if flip_mode:
            conn_mode[0] = "negotiate" if conn_mode[0] == "direct" else "direct"
        log_msg(pair_id, f"🔁 Stream-Verbindung wird neu aufgebaut — {reason}")
        old = hub
        hub = build_hub(s["tsxToken"])
        mirror_hubs[pair_id] = hub
        _hub_kill(old)
        start_hub_async(hub)

    # STREAM-AUFBAU NIE IN DER KOPIER-SCHLEIFE (17.09.2026, Finn: 'es funktioniert
    # nicht … such den Fehler' — zwei Test-Trades auf Chriss' PC bei grünem Start-Check
    # nicht gespiegelt). In der Nachstellung (Schein-TSX/-Hub/-MetaApi gegen die ECHTE
    # Engine) gefunden: signalrcore 1.0.2 baut Verbindungen OHNE jeden Timeout auf
    # (socket.create_connection + blockierendes recv auf die Upgrade-Antwort, negotiate
    # ebenso). hub.start() lief bisher SYNCHRON in dieser Worker-Schleife — bei jedem
    # Neuaufbau (Modus-Flip alle ~10s im Sturm, Parken, Heal, Token). Antwortet der
    # Server einmal nicht, steht die GANZE Schleife: kein Abgleich, keine Kopie, kein
    # Heartbeat — und das Pair zeigt weiter 'scharf'. Zweiter Fehler an derselben
    # Stelle: scheiterte der ALLERERSTE Aufbau mit einer Exception, machte die Engine
    # 'return' — Session blieb active, kopiert hat nichts mehr ('gar nicht kopiert,
    # egal wie lange ich warte'). Die Kopien hängen aber gar nicht am Stream, sondern
    # am 1s-Abgleich. Deshalb: start() in einem eigenen Daemon-Thread; Fehler und
    # Hänger (20s-Wächter in der Schleife) parken nur den STREAM, nie das Kopieren.
    hub_start = {"t": 0.0, "done": True}
    def start_hub_async(h):
        hub_start["t"] = time.time()
        hub_start["done"] = False
        def _run():
            try:
                h.start()
            except Exception as e:
                if session_alive() and hub_is_current(h):
                    log_msg(pair_id, f"❌ Stream-Aufbau fehlgeschlagen: {type(e).__name__}: {str(e)[:120]} — der 1s-Abgleich kopiert weiter, nächster Stream-Versuch in 60s", "warn")
                    stream_parked[0] = time.time() + 60
                    closes_noevent[0] = 0
            finally:
                if hub_is_current(h):
                    hub_start["done"] = True
        threading.Thread(target=_run, daemon=True).start()

    hub = build_hub(s["tsxToken"])
    mirror_hubs[pair_id] = hub  # VOR start() registrieren — on_open kann sofort feuern
    start_hub_async(hub)

    if s.get("sltpSync"):
        threading.Thread(target=_sltp_worker, args=(pair_id, s, ref, pos_lock, snapshot), daemon=True).start()

    # Reconciliation-Watchdog mit SELBSTHEILUNG (21.07.2026): der Live-Test hat gezeigt,
    # dass der SignalR-Stream de facto ausfallen kann (Reconnect-Burst beim Start, danach
    # nominell verbunden, aber keine Events mehr) — reine Warnungen halfen Finn nicht,
    # die Position blieb ungespiegelt bis zum manuellen Neustart. Deshalb handelt der
    # Abgleich jetzt selbst:
    #  - Position auf TSX ohne lokalen Hedge → sofort per sync_baseline(heal) übernehmen
    #    (racefrei durch pos_lock + ref-Check; schlimmstenfalls ~3-6s Latenz statt nie).
    #  - Lokal getrackt, aber auf TSX weg → Hedge schließen, aber erst nach 2 Pässen in
    #    Folge (~6s): schützt gegen den Race, dass ein frisch per Event eröffneter Trade
    #    im gerade gezogenen (älteren) REST-Snapshot noch fehlt.
    #  - Nach jedem Heal gilt der Stream als defekt → Verbindung wird neu aufgebaut
    #    (max. 1×/60s, damit kein Rebuild-Loop entsteht).
    last_heartbeat = time.time()
    HEARTBEAT_INTERVAL = 120
    while session_alive():
        if _token_tot_beenden(pair_id, s):
            break
        if time.time() - s.get("lastTokenRefresh", 0) > TOKEN_REFRESH_INTERVAL:
            if refresh_tsx_token(pair_id, http):
                # Frischer Token → Hub braucht neue Verbindung (access_token steckt in der URL)
                rebuild_connection("Token erneuert")

        if time.time() - last_heartbeat > HEARTBEAT_INTERVAL:
            n_open = len(ref)
            log_msg(pair_id, f"💓 Mirror läuft (Echtzeit) — {n_open} offene Position{'en' if n_open != 1 else ''} · {reconnects[0]} Reconnects bisher")
            last_heartbeat = time.time()

        # ── Close-Sturm-Behandlung (08.09.2026, Mac-Live-Befund) ──
        # Server schließt ~2s nach jedem Abonnieren (CloseMessage ohne Grund, keine
        # Abo-Bestätigung), Library reconnectet endlos — Events kommen NIE durch, die
        # 1s-Reconciliation macht die eigentliche Kopier-Arbeit (Finns "1-3s zu langsam").
        # Der Heal-gebundene Modus-Flip feuerte bei flachem Konto nie. Jetzt: nach 5
        # Closes ohne ein einziges Event Modus wechseln (direct↔negotiate); haben beide
        # Modi zusammen 4 Wechsel verloren, wird der Stream 60s GEPARKT (hub.stop() statt
        # Dauerhämmern → kein 429-Risiko) und danach frisch versucht. Kopien laufen in
        # der Park-Zeit unverändert über den 1s-Abgleich.
        if not hub_start["done"] and not stream_parked[0] and time.time() - hub_start["t"] > 20:
            hub_start["done"] = True
            log_msg(pair_id, "⏳ Stream-Aufbau hängt seit 20s (Server antwortet nicht) — abgebrochen, Stream 60s geparkt. Der 1s-Abgleich kopiert unverändert weiter.", "warn")
            stream_parked[0] = time.time() + 60
            closes_noevent[0] = 0
            _hub_kill(hub)

        if stream_parked[0]:
            if time.time() >= stream_parked[0]:
                stream_parked[0] = 0
                closes_noevent[0] = 0
                rebuild_connection("Stream-Pause vorbei — neuer Versuch")
        elif closes_noevent[0] >= 5 and stream_events[0] == 0:
            flip_tries[0] += 1
            if flip_tries[0] >= 4:
                log_msg(pair_id, "⏸️ Beide Verbindungsmodi werden vom Server sofort geschlossen (0 Events) — Stream 60s pausiert, der 1s-Abgleich kopiert weiter. Häufigste Ursache: ein ZWEITER Client auf demselben TSX-Login hält den User-Hub (andere Mirror-Engine auf einem anderen Backend/PC, oder ein Tool mit demselben API-Key).", "warn")
                stream_parked[0] = time.time() + 60
                flip_tries[0] = 0
                closes_noevent[0] = 0
                _hub_kill(hub)
            else:
                closes_noevent[0] = 0
                rebuild_connection(f"Close-Sturm ohne Events — Modus-Wechsel #{flip_tries[0]}", flip_mode=True)

        try:
            r = http.post(f"{TSX_BASE}/api/Position/searchOpen",
                headers={"Authorization": f"Bearer {s['tsxToken']}", "Content-Type": "application/json"},
                json={"accountId": int(s["tsxAccountId"])}, timeout=10)
            if r.ok:
                positions = r.json().get("positions", r.json().get("data", []))
                snapshot[0], snapshot[1] = time.time(), positions
                rest_contracts = {p.get("contractId") for p in positions if p.get("contractId")}
                with pos_lock:
                    tracked_contracts = {c for c, q in net.items() if q != 0}
                missing_locally = rest_contracts - tracked_contracts    # TSX hat's, wir nicht
                if s.get("opensBlocked") and missing_locally:
                    for c in missing_locally: open_gesperrt(c)   # einmal pro Contract sagen …
                    missing_locally = set()                      # … aber nichts übernehmen/neu aufbauen
                phantom_locally = tracked_contracts - rest_contracts    # wir haben's, TSX nicht mehr
                healed = False

                if missing_locally:
                    log_msg(pair_id, f"🛟 Abgleich: {len(missing_locally)} TSX-Position(en) ohne Hedge ({', '.join(list(missing_locally)[:3])}) — übernehme automatisch…", "warn")
                    if sync_baseline(heal=True, snapshot=positions) > 0:
                        healed = True

                # Phantom = lokal getrackt, auf TSX weg → Hedge schließen. EIN Pass reicht,
                # solange die Position älter ist als der REST-Snapshot sein kann (2,5s) —
                # der alte 2-Pass-Zähler kostete beim Schließen 4-6s (Finns Kritik 21.07.).
                # Frisch eröffnete Positionen (< 2,5s) überspringen: der gerade verarbeitete
                # Snapshot könnte VOR ihrer Eröffnung gezogen worden sein (Race).
                for c in phantom_locally:
                    if time.time() - opened_at.get(c, 0) < 2.5:
                        continue
                    with pos_lock:
                        rid = ref.pop(c, None)
                        net[c] = 0
                        opened_at.pop(c, None)
                    log_msg(pair_id, f"🛟 Abgleich: {c} auf TSX geschlossen — schließe Hedge automatisch…", "warn")
                    if rid:
                        close_hedge(pair_id, rid)
                    healed = True
                pruef_one_shot()
                # Hedge-Zuordnung für den Neustart sichern — nur bei Änderung
                with pos_lock:
                    _rs = {c: {"rid": ref[c], "net": net.get(c, 0)} for c in ref}
                _sig = json.dumps(_rs, sort_keys=True) + str(had_pos[0])
                if _sig != state_sig[0]:
                    state_sig[0] = _sig
                    s["refState"], s["hadPos"] = _rs, had_pos[0]
                    _sessions_save()

                if healed:
                    # Nach 3 Neuaufbau-Versuchen ohne dass der Stream je geliefert hat:
                    # Frequenz auf 5 min drosseln — die Reconnect-Stürme haben beim Live-Test
                    # serverseitig HTTP 429 (Rate-Limit) provoziert und machen es nur schlimmer.
                    cooldown = 60 if rebuild_count[0] < 3 else 300
                    if last_rebuild[0] == 0 or time.time() - last_rebuild[0] > cooldown:
                        last_rebuild[0] = time.time()
                        rebuild_count[0] += 1
                        # Hat der Stream in diesem Verbindungsmodus noch NIE ein Event geliefert,
                        # ist der Modus selbst verdächtig → beim Neuaufbau auf den anderen wechseln
                        # (direct ↔ negotiate). Kamen früher schon Events, Modus beibehalten.
                        rebuild_connection("Stream hat Events verpasst", flip_mode=(stream_events[0] == 0))
            elif time.time() - rec_warn[0] > 30:
                # Bisher STILL verschluckt (17.09.2026): antwortet TSX mit 429 (Rate-Limit)
                # oder 5xx, ist der Abgleich — und damit das gesamte Kopieren — blind,
                # ohne dass irgendwo eine Zeile stand. Gedrosselt auf 1×/30s.
                rec_warn[0] = time.time()
                log_msg(pair_id, f"⚠️ Abgleich blind: TSX antwortet HTTP {r.status_code} auf Position/searchOpen{' (Rate-Limit)' if r.status_code == 429 else ''} — solange wird NICHT kopiert. {r.text[:80]}", "warn")
        except Exception as e:
            # Der Abgleich IST das Kopieren (solange der Stream keine Events liefert) —
            # Fehler stoppen den Mirror weiter nicht, bleiben aber nicht mehr unsichtbar.
            if time.time() - rec_warn[0] > 30:
                rec_warn[0] = time.time()
                log_msg(pair_id, f"⚠️ Abgleich-Fehler: {type(e).__name__}: {str(e)[:100]} — solange wird NICHT kopiert", "warn")

        time.sleep(RT_RECONCILE_INTERVAL)

    if mirror_hubs.get(pair_id) is hub:
        mirror_hubs.pop(pair_id, None)
    _hub_kill(hub)
    try:
        _sr_logger.removeHandler(_sr_bridge)
    except Exception:
        pass
    http.close()
    log_msg(pair_id, "Mirror gestoppt")

# ── NOTFALL-SL/TP für den Topstep-Mirror (17.09.2026) ──
# Finn: 'Das Gleiche wie bei den Notfall-TP und -SL bei Echo: ich verschiebe auf Topstep
# SL und TP per Drag & Drop (öfter pro Trade) — dann sollen auf Fusion SL und TP
# automatisch in diesem Verhältnis mitwandern.'
# RECHNUNG = Echo (mt5-copier/copier.py plan_sltp), bewusst dieselbe Doktrin:
#   gekreuzt (Master-SL → Hedge-TP, Master-TP → Hedge-SL), Puffer IMMER in Auslöse-
#   richtung HINTER dem Master-Level: (faktor−100)% der Distanz Entry↔Level, mindestens
#   puffer_min_punkte × point. NIE 'Entry ± Faktor × Distanz' (bricht beim SL im Gewinn).
# EIN UNTERSCHIED zu Echo, erzwungen durch die Sache: Master ist ein FUTURE (NQ/MNQ),
#   der Hedge ein Kassa-CFD (NAS100) — die Kurse liegen dauerhaft um die Basis auseinander.
#   Absolute Level lassen sich also nicht übernehmen. Übertragen wird der ABSTAND zum
#   Entry: Hedge-Level = Hedge-Entry + (Level − Master-Entry). Weil der Hedge ~1 s nach
#   dem Master eröffnet, steckt in dieser Basis ein Fehler von ein paar Punkten — deshalb
#   hier ein Mindest-Puffer-BODEN in Indexpunkten, unabhängig von den Echo-Werten. Sonst
#   könnte ein Hedge-Level knapp VOR dem Master-Level liegen und der Hedge schlösse,
#   während der Master weiterläuft.
# LÄUFT IN EINEM EIGENEN THREAD (Finns Ansage 'an der Latenz nichts ändern'): die Kopier-
#   Schleife wird weder um Requests noch um Wartezeit verlängert. Einziger Zusatz-Request:
#   Order/searchOpen alle 2 s und NUR solange ein Hedge offen ist.
MIRROR_SLTP_INTERVAL = 2.0
MIRROR_SLTP_PUFFER_BODEN = 5.0   # Indexpunkte, s.o.

def mirror_plan_sltp(*, lang, entry_m, msl, mtp, entry_h, faktor, min_puffer, digits):
    """REIN RECHNEND (testbar). lang = Master ist Long. msl/mtp = Master-SL/TP oder None.
    Rückgabe {'tp': x|None, 'sl': y|None} in Hedge-Kursen (None = Level entfernen)."""
    def hinter(level, richtung):  # richtung: -1 = löst bei fallendem Kurs aus, +1 = steigend
        puffer = max((float(faktor) / 100.0 - 1.0) * abs(float(level) - float(entry_m)), float(min_puffer))
        ziel_m = float(level) + richtung * puffer
        return round(float(entry_h) + (ziel_m - float(entry_m)), int(digits))
    return {"tp": hinter(msl, -1 if lang else +1) if msl else None,
            "sl": hinter(mtp, +1 if lang else -1) if mtp else None}

def _sltp_worker(pair_id, s, ref, pos_lock, snapshot):
    http = requests.Session(); http.verify = False
    spec = {}      # mt_symbol -> {"digits": n, "point": x}
    hedge = {}     # mtPosId -> {"open": preis}
    last = {}      # mtPosId -> (sl, tp) zuletzt gesetzt
    warn_ts = [0.0]
    def warn(msg):
        if time.time() - warn_ts[0] > 30:
            warn_ts[0] = time.time()
            log_msg(pair_id, msg, "warn")
    ma = lambda path: f"{MA_BASE}/users/current/accounts/{s['maAccountId']}{path}"
    mah = {"auth-token": s["maToken"], "Content-Type": "application/json"}
    log_msg(pair_id, f"🎯 Notfall-SL/TP aktiv: Faktor {s.get('notfallFaktor')}% · Mindest-Puffer {s.get('notfallPufferPunkte')} Punkte (Boden {MIRROR_SLTP_PUFFER_BODEN} Indexpunkte) — Master-Level werden alle {int(MIRROR_SLTP_INTERVAL)} s gelesen")
    while mirror_sessions.get(pair_id) is s and s.get("active"):
        time.sleep(MIRROR_SLTP_INTERVAL)
        try:
            with pos_lock:
                offen = {c: s["positions"].get(rid) for c, rid in ref.items()}
            offen = {c: pid for c, pid in offen.items() if pid}
            if not offen:
                continue
            if time.time() - snapshot[0] > 10:
                continue  # Abgleich blind/alt → kein belastbarer Master-Entry, nichts anfassen
            r = http.post(f"{TSX_BASE}/api/Order/searchOpen",
                headers={"Authorization": f"Bearer {s['tsxToken']}", "Content-Type": "application/json"},
                json={"accountId": int(s["tsxAccountId"])}, timeout=8)
            if not r.ok:
                warn(f"⚠️ Notfall-SL/TP: TSX Order/searchOpen HTTP {r.status_code} — Level bleiben, wie sie sind")
                continue
            orders = [o for o in (r.json().get("orders") or []) if o.get("status") in (1, None)]
            for c, pid in offen.items():
                mpos = next((p for p in snapshot[1] if p.get("contractId") == c), None)
                if not mpos or not mpos.get("averagePrice"):
                    continue
                lang = mpos.get("type") == 1
                entry_m = float(mpos["averagePrice"])
                gegen = 1 if lang else 0   # Seite der Schutz-Orders: Long → Sell(1), Short → Buy(0)
                eig = [o for o in orders if o.get("contractId") == c and o.get("side") == gegen]
                stops  = [float(o["stopPrice"])  for o in eig if o.get("type") in (4, 5) and o.get("stopPrice")]
                limits = [float(o["limitPrice"]) for o in eig if o.get("type") == 1 and o.get("limitPrice")]
                # Mehrere Level (Teil-Ausstiege): das ENTFERNTESTE zählt — der Hedge behält
                # seine Größe bis zum vollen Master-Close, also darf kein früheres Teilziel
                # den ganzen Hedge schließen.
                msl = (min(stops) if lang else max(stops)) if stops else None
                mtp = (max(limits) if lang else min(limits)) if limits else None

                parts = c.split(".")
                base = parts[3] if len(parts) > 3 else (parts[2] if len(parts) > 2 else c[:3])
                sym = s["symbolMap"].get(base, "NAS100")
                if sym not in spec:
                    rs = http.get(ma(f"/symbols/{sym}/specification"), headers=mah, timeout=10)
                    if not rs.ok:
                        warn(f"⚠️ Notfall-SL/TP: Symbol-Spezifikation {sym} HTTP {rs.status_code}")
                        continue
                    d = rs.json()
                    dg = int(d.get("digits", 2))
                    spec[sym] = {"digits": dg, "point": float(d.get("point") or 10 ** (-dg))}
                if pid not in hedge:
                    rp = http.get(ma(f"/positions/{pid}"), headers=mah, timeout=10)
                    if not rp.ok or not rp.json().get("openPrice"):
                        warn(f"⚠️ Notfall-SL/TP: Hedge-Position {pid} nicht lesbar (HTTP {rp.status_code}) — nächster Versuch in {int(MIRROR_SLTP_INTERVAL)} s")
                        continue
                    hedge[pid] = {"open": float(rp.json()["openPrice"])}
                min_puffer = max(float(s.get("notfallPufferPunkte") or 0) * spec[sym]["point"], MIRROR_SLTP_PUFFER_BODEN)
                ziel = mirror_plan_sltp(lang=lang, entry_m=entry_m, msl=msl, mtp=mtp, entry_h=hedge[pid]["open"],
                    faktor=s.get("notfallFaktor") or 110.0, min_puffer=min_puffer, digits=spec[sym]["digits"])
                neu = (ziel["sl"], ziel["tp"])
                if last.get(pid, (None, None)) == neu:
                    continue
                body = {"actionType": "POSITION_MODIFY", "positionId": pid}
                if ziel["sl"] is not None: body["stopLoss"] = ziel["sl"]
                if ziel["tp"] is not None: body["takeProfit"] = ziel["tp"]
                rm = http.post(ma("/trade"), headers=mah, json=body, timeout=15)
                if rm.ok:
                    last[pid] = neu
                    log_msg(pair_id, f"🎯 Notfall-SL/TP gesetzt: Hedge-TP {ziel['tp'] if ziel['tp'] is not None else '—'} (Master-SL {msl if msl is not None else '—'}) · Hedge-SL {ziel['sl'] if ziel['sl'] is not None else '—'} (Master-TP {mtp if mtp is not None else '—'}) · Basis {hedge[pid]['open'] - entry_m:+.2f}", "ok")
                else:
                    warn(f"⚠️ Notfall-SL/TP: MetaApi lehnt ab — HTTP {rm.status_code} {rm.text[:120]}")
        except Exception as e:
            warn(f"⚠️ Notfall-SL/TP: {type(e).__name__}: {str(e)[:100]}")
    http.close()

def _instr_scale(fill_base, plan_base):
    """Micro/Mini-Umrechnung innerhalb einer Kontrakt-Familie (Faktor 10).
    Der Multiplier eines Plans bezieht sich auf EIN Instrument (z.B. Lots je NQ);
    fällt der echte Fill auf dem Schwester-Kontrakt (MNQ), muss die Lot-Größe
    durch 10 — sonst wäre der Hedge um Faktor 10 falsch. ProjectX benennt die
    E-minis in Contract-IDs teils ENQ/EP, deshalb beide Schreibweisen."""
    minis  = {"NQ": "NQ", "ENQ": "NQ", "ES": "ES", "EP": "ES", "YM": "YM"}
    micros = {"MNQ": "NQ", "MES": "ES", "MYM": "YM"}
    def norm(x):
        x = str(x or "").upper()
        if x in micros: return (micros[x], "micro")
        if x in minis:  return (minis[x], "mini")
        return (x, None)
    ff, fk = norm(fill_base)
    pf, pk = norm(plan_base)
    if ff != pf or fk is None or pk is None or fk == pk:
        return 1.0
    return 10.0 if (pk == "micro" and fk == "mini") else 0.1

def open_hedge(pair_id, order_id, side, contract, qty, tsx_risk_usd=0):
    s = mirror_sessions.get(pair_id)
    if not s: return

    parts = contract.split(".")
    base = parts[3] if len(parts) > 3 else (parts[2] if len(parts) > 2 else contract[:3])
    mt_symbol = s["symbolMap"].get(base, "NAS100")

    target_eur = float(s.get("targetRiskEur", 0))
    multiplier = float(s.get("multiplier", 1.0))

    if target_eur > 0 and tsx_risk_usd > 0:
        lots = round((target_eur / tsx_risk_usd) * qty * 2.33, 2)
        log_msg(pair_id, f"Lot Berechnung: ({target_eur}€ / ${tsx_risk_usd}) × {qty} × 2.33 = {lots}")
    else:
        scale = _instr_scale(base, s.get("baseInstrument", "MNQ"))
        lots = round(qty * multiplier * scale, 2)
        if scale != 1.0:
            log_msg(pair_id, f"⚖️ Kontrakt-Umrechnung: Fill auf {base}, Multiplier-Basis {s.get('baseInstrument','MNQ')} → Faktor {scale} → {lots} Lots")

    lots = max(0.01, lots)

    mt_side = "ORDER_TYPE_SELL" if side in (0, "0", "Buy", "buy", "BUY", "Long", "long", "B") else "ORDER_TYPE_BUY"

    body = {"symbol": mt_symbol, "volume": lots, "actionType": mt_side, "comment": f"HM-{str(order_id)[:8]}"}

    # Eigene Session pro hedge-call ist OK (kurzlebig), aber wir wollen nicht bei Connection-Errors crashen
    try:
        r = requests.post(
            f"{MA_BASE}/users/current/accounts/{s['maAccountId']}/trade",
            headers={"auth-token": s["maToken"], "Content-Type": "application/json"},
            json=body, timeout=15, verify=False)
        try:
            d = r.json()
        except (ValueError, requests.exceptions.JSONDecodeError):
            d = {}
        if r.ok:
            pos_id = str(d.get("positionId") or d.get("orderId", ""))
            s["positions"][order_id] = pos_id
            log_msg(pair_id, f"✅ Hedge OPEN: {mt_side.split('_')[-1]} {lots}x {mt_symbol} | pos={pos_id}")
        else:
            log_msg(pair_id, f"❌ Open failed: {r.status_code} {r.text[:150]}")
    except requests.exceptions.Timeout:
        log_msg(pair_id, f"⏱ Open timeout (Trade ggf. trotzdem ausgeführt — bitte MT5 prüfen!)")
    except requests.exceptions.ConnectionError as e:
        log_msg(pair_id, f"🔌 Open connection error: {str(e)[:100]}")
    except Exception as e:
        log_msg(pair_id, f"❌ Open error: {type(e).__name__}: {str(e)[:120]}")

def close_hedge(pair_id, ref_id):
    s = mirror_sessions.get(pair_id)
    if not s: return

    pos_id = s["positions"].get(ref_id)
    if not pos_id:
        # Falls die Master-Position bereits manuell geschlossen wurde, ignorieren
        log_msg(pair_id, f"ℹ️ Keine gespiegelte MT-Position für {ref_id} (manuell geschlossen?)")
        return

    body = {"actionType": "POSITION_CLOSE_ID", "positionId": pos_id}
    try:
        r = requests.post(
            f"{MA_BASE}/users/current/accounts/{s['maAccountId']}/trade",
            headers={"auth-token": s["maToken"], "Content-Type": "application/json"},
            json=body, timeout=15, verify=False)
        if r.ok:
            log_msg(pair_id, f"✅ Hedge CLOSED: pos={pos_id}")
            s["positions"].pop(ref_id, None)
            # Geschlossene Hedge-IDs behalten — das Auto-PnL-Prefill im Trade-Complete-
            # Modal matcht darüber die MetaApi-Deals (die positions-Map verliert die ID
            # ja gerade beim Schließen). Cap gegen unbegrenztes Wachstum.
            s.setdefault("closedHedges", []).append({"mtPosId": str(pos_id), "ts": time.time()})
            if len(s["closedHedges"]) > 50:
                s["closedHedges"] = s["closedHedges"][-50:]
            _sessions_save()
        else:
            # Wenn die Position auf MT-Seite schon weg ist (404 oder 4xx-Fehler), trotzdem aus dem Tracking entfernen
            err_text = r.text[:100]
            log_msg(pair_id, f"❌ Close failed: {r.status_code} {err_text}")
            if r.status_code == 404 or "not found" in err_text.lower() or "no position" in err_text.lower():
                log_msg(pair_id, f"ℹ️ MT-Position bereits weg — entferne aus Tracking")
                s["positions"].pop(ref_id, None)
    except requests.exceptions.Timeout:
        log_msg(pair_id, f"⏱ Close timeout (Position ggf. trotzdem geschlossen — bitte MT5 prüfen!)")
    except requests.exceptions.ConnectionError as e:
        log_msg(pair_id, f"🔌 Close connection error: {str(e)[:100]}")
    except Exception as e:
        log_msg(pair_id, f"❌ Close error: {type(e).__name__}: {str(e)[:120]}")

def log_msg(pair_id, msg, kind=None):
    """
    Log eine Message für ein Pair. kind ist optional ('ok', 'warn', 'err', 'info').
    Wenn nicht angegeben, wird's aus dem Emoji-Präfix abgeleitet.
    """
    print(f"[{pair_id}] {msg}")
    if pair_id not in mirror_sessions:
        return

    # Auto-Detect kind aus Emoji wenn nicht explizit angegeben
    if kind is None:
        first_chars = msg[:3] if msg else ""
        if any(e in first_chars for e in ["✅", "🔄", "🆕", "📊"]):
            kind = "ok"
        elif any(e in first_chars for e in ["❌", "💥", "⛔", "🔒"]):
            kind = "err"
        elif any(e in first_chars for e in ["⚠️", "⏱", "🔌", "📦"]):
            kind = "warn"
        else:
            kind = "info"

    mirror_sessions[pair_id]["log"].append({
        "ts": time.strftime("%H:%M:%S"),
        "msg": msg,
        "kind": kind
    })
    # Log-Größe begrenzen damit RAM nicht explodiert
    if len(mirror_sessions[pair_id]["log"]) > 500:
        mirror_sessions[pair_id]["log"] = mirror_sessions[pair_id]["log"][-500:]

# ── MT5 → TopstepX Mirror ──
def run_mirror_mt_to_tsx(pair_id):
    s = mirror_sessions.get(pair_id)
    if not s: return

    http = requests.Session()
    http.verify = False

    log_msg(pair_id, f"🚀 Mirror gestartet — MT5 → TSX")
    log_msg(pair_id, f"📊 MT5 Account: {s.get('maAccountId','?')} · TSX Account: {s.get('tsxAccountId','?')}")
    log_msg(pair_id, f"⚙️ Multiplier: {s.get('multiplier', 1.0)}x")
    log_msg(pair_id, f"⏱ Polling-Intervall: {s.get('pollInterval', 0.5)}s")

    known_positions = {}
    consecutive_errors = 0
    last_heartbeat = time.time()
    HEARTBEAT_INTERVAL = 120
    MAX_BACKOFF = 60

    # Session-Identität statt nur active-Flag — siehe Kommentar in run_mirror (Zombie-Bug)
    while mirror_sessions.get(pair_id) is s and s.get("active"):
        if _token_tot_beenden(pair_id, s):
            break
        # TSX Token auch hier refreshen (brauchen wir für close orders)
        if time.time() - s.get("lastTokenRefresh", 0) > TOKEN_REFRESH_INTERVAL:
            refresh_tsx_token(pair_id, http)

        # Heartbeat
        if time.time() - last_heartbeat > HEARTBEAT_INTERVAL:
            n_open = len(known_positions)
            log_msg(pair_id, f"💓 Mirror läuft — {n_open} offene Position{'en' if n_open != 1 else ''}")
            last_heartbeat = time.time()

        try:
            r = http.get(
                f"{MA_BASE}/users/current/accounts/{s['maAccountId']}/positions",
                headers={"auth-token": s["maToken"], "Content-Type": "application/json"},
                timeout=15)

            if not r.ok:
                consecutive_errors += 1
                backoff = min(MAX_BACKOFF, 2 ** min(consecutive_errors, 6))
                log_msg(pair_id, f"MT Poll error: {r.status_code} — warte {backoff}s")
                time.sleep(backoff)
                continue

            consecutive_errors = 0

            positions = r.json()
            if not isinstance(positions, list):
                positions = positions.get("positions", [])

            current = {str(p.get("id", "")): p for p in positions}

            for pid, pos in current.items():
                if pid not in known_positions:
                    mt_type = pos.get("type", "")
                    mt_symbol = pos.get("symbol", "")
                    mt_volume = float(pos.get("volume", 1))
                    tsx_symbol = s["reverseSymbolMap"].get(mt_symbol, "MNQ")
                    if "BUY" in str(mt_type).upper():
                        tsx_side = 1
                        side_label = "Sell"
                    else:
                        tsx_side = 0
                        side_label = "Buy"
                    qty = max(1, round(mt_volume * s["multiplier"]))
                    log_msg(pair_id, f"🆕 MT5 Position erkannt: {mt_type} {mt_volume}× {mt_symbol}")
                    log_msg(pair_id, f"➡️ Spiegle nach TSX als {side_label} {qty}× {tsx_symbol}…")
                    open_tsx_hedge(pair_id, pid, tsx_side, tsx_symbol, qty)
                    last_heartbeat = time.time()

            for pid in list(known_positions.keys()):
                if pid not in current:
                    log_msg(pair_id, f"🔚 MT5 Position geschlossen: {pid[:12]}…")
                    log_msg(pair_id, f"➡️ Schließe Hedge auf TSX…")
                    try:
                        r2 = http.post(f"{TSX_BASE}/api/Position/searchOpen",
                            headers={"Authorization": f"Bearer {s['tsxToken']}", "Content-Type": "application/json"},
                            json={"accountId": int(s["tsxAccountId"])}, timeout=10)
                        if r2.status_code == 401:
                            refresh_tsx_token(pair_id, http)
                            r2 = http.post(f"{TSX_BASE}/api/Position/searchOpen",
                                headers={"Authorization": f"Bearer {s['tsxToken']}", "Content-Type": "application/json"},
                                json={"accountId": int(s["tsxAccountId"])}, timeout=10)
                        tsx_positions = r2.json().get("positions", [])
                        if not tsx_positions:
                            log_msg(pair_id, f"ℹ️ Keine offenen TSX-Positionen — bereits geschlossen?")
                        for tpos in tsx_positions:
                            ttype = tpos.get("type", 0)
                            tsize = int(tpos.get("size", 1))
                            tcontract = tpos.get("contractId", "CON.F.US.MNQ.M26")
                            close_side = 1 if ttype == 1 else 0
                            close_body = {
                                "accountId": int(s["tsxAccountId"]),
                                "contractId": tcontract,
                                "type": 2,
                                "side": close_side,
                                "size": tsize
                            }
                            cr = http.post(f"{TSX_BASE}/api/Order/place",
                                headers={"Authorization": f"Bearer {s['tsxToken']}", "Content-Type": "application/json"},
                                json=close_body, timeout=10)
                            if cr.ok:
                                log_msg(pair_id, f"✅ TSX Close Order gesendet: {tsize}× {tcontract}")
                            else:
                                log_msg(pair_id, f"❌ TSX Close Order failed: {cr.status_code} {cr.text[:80]}")
                    except Exception as e:
                        log_msg(pair_id, f"❌ TSX Close error: {type(e).__name__}: {str(e)[:120]}")
                    last_heartbeat = time.time()
                    if pid in s["positions"]:
                        del s["positions"][pid]

            known_positions = current

        except requests.exceptions.Timeout:
            consecutive_errors += 1
            backoff = min(MAX_BACKOFF, 2 ** min(consecutive_errors, 6))
            log_msg(pair_id, f"⏱ MT Timeout — warte {backoff}s")
            time.sleep(backoff)
            continue
        except requests.exceptions.ConnectionError as e:
            consecutive_errors += 1
            backoff = min(MAX_BACKOFF, 2 ** min(consecutive_errors, 6))
            log_msg(pair_id, f"🔌 MT Connection error: {str(e)[:80]} — warte {backoff}s")
            time.sleep(backoff)
            continue
        except (requests.exceptions.JSONDecodeError, ValueError, KeyError, TypeError) as e:
            consecutive_errors += 1
            backoff = min(MAX_BACKOFF, 2 ** min(consecutive_errors, 6))
            log_msg(pair_id, f"📦 Bad data from MT: {type(e).__name__} {str(e)[:80]} — warte {backoff}s")
            time.sleep(backoff)
            continue
        except Exception as e:
            consecutive_errors += 1
            backoff = min(MAX_BACKOFF, 2 ** min(consecutive_errors, 6))
            log_msg(pair_id, f"⚠️ MT Unerwarteter Fehler: {type(e).__name__}: {str(e)[:120]} — warte {backoff}s")
            time.sleep(backoff)
            continue

        time.sleep(s.get("pollInterval", 0.5))

    http.close()
    log_msg(pair_id, "MT→TSX Mirror gestoppt")

def open_tsx_hedge(pair_id, mt_pos_id, side, contract_base, qty):
    s = mirror_sessions.get(pair_id)
    if not s: return

    contract_map = {
        "MNQ": "CON.F.US.MNQ.M26",
        "NQ":  "CON.F.US.ENQ.M26",
        "MES": "CON.F.US.MES.M26",
        "ES":  "CON.F.US.EP.M26",
        "MYM": "CON.F.US.MYM.M26",
        "YM":  "CON.F.US.YM.M26",
    }
    contract_id = contract_map.get(contract_base, f"CON.F.US.{contract_base}.M26")

    body = {
        "accountId": int(s["tsxAccountId"]),
        "contractId": contract_id,
        "type": 2,
        "side": side,
        "size": qty,
        "customTag": f"HM-MT-{mt_pos_id[:8]}"
    }

    try:
        r = requests.post(f"{TSX_BASE}/api/Order/place",
            headers={"Authorization": f"Bearer {s['tsxToken']}", "Content-Type": "application/json"},
            json=body, timeout=10)
        # Bei 401 kurz refreshen und nochmal probieren
        if r.status_code == 401:
            tmp_session = requests.Session()
            if refresh_tsx_token(pair_id, tmp_session):
                r = requests.post(f"{TSX_BASE}/api/Order/place",
                    headers={"Authorization": f"Bearer {s['tsxToken']}", "Content-Type": "application/json"},
                    json=body, timeout=10)
            tmp_session.close()
        d = r.json()
        if d.get("success") or d.get("orderId"):
            order_id = str(d.get("orderId", ""))
            s["positions"][mt_pos_id] = order_id
            log_msg(pair_id, f"✅ TSX Order: {'Sell' if side==1 else 'Buy'} {qty}x {contract_base} | orderId={order_id}")
        else:
            log_msg(pair_id, f"❌ TSX Order failed: {d.get('errorMessage', d)}")
    except Exception as e:
        log_msg(pair_id, f"❌ TSX Order error: {e}")

def close_tsx_hedge(pair_id, mt_pos_id):
    s = mirror_sessions.get(pair_id)
    if not s: return

    if mt_pos_id not in s["positions"]:
        log_msg(pair_id, f"Keine TSX Position für MT {mt_pos_id}")
        return

    try:
        r = requests.post(f"{TSX_BASE}/api/Position/searchOpen",
            headers={"Authorization": f"Bearer {s['tsxToken']}", "Content-Type": "application/json"},
            json={"accountId": int(s["tsxAccountId"])}, timeout=10)
        positions = r.json().get("positions", [])

        for pos in positions:
            pos_id = str(pos.get("id", ""))
            if pos_id in s["positions"].values():
                close_r = requests.post(f"{TSX_BASE}/api/Position/closeAll",
                    headers={"Authorization": f"Bearer {s['tsxToken']}", "Content-Type": "application/json"},
                    json={"accountId": int(s["tsxAccountId"])},
                    timeout=10)
                d = close_r.json()
                if close_r.ok or d.get("success"):
                    log_msg(pair_id, f"✅ TSX Position geschlossen")
                else:
                    log_msg(pair_id, f"❌ TSX Close: {d}")
                if mt_pos_id in s["positions"]:
                    del s["positions"][mt_pos_id]
                break
        else:
            log_msg(pair_id, f"TSX Position bereits geschlossen")
            if mt_pos_id in s["positions"]:
                del s["positions"][mt_pos_id]

    except Exception as e:
        log_msg(pair_id, f"❌ TSX Close error: {e}")

@app.route("/debug/account", methods=["POST","OPTIONS"])
def debug_account():
    if request.method == "OPTIONS": return "", 200
    token = request.headers.get("Authorization","").replace("Bearer ","")
    r = requests.post(f"{TSX_BASE}/api/Account/search",
        json={"onlyActive": True},
        headers={"Authorization": f"Bearer {token}","Content-Type":"application/json"},
        timeout=10)
    return Response(r.content, status=r.status_code, content_type="application/json")

# ════════════════════════════════════════════════════════════════════════════
# SERVER-WÄCHTER — Trade-Erkennung 24/7, unabhängig vom Browser (04.08.2026)
#
# Finns Anforderung: die drei Schritte Geplant→Läuft→Überprüfen + Auto-P&L
# müssen DURCHGEHEND laufen — auch wenn kein Prophos-Tab offen ist und egal,
# in welchem Profil er gerade eingeloggt ist. Der Browser-Wächter (mpWatch)
# war der Zwischenschritt; das hier ist die echte Lösung: dieselbe Erkennung
# als Server-Loop auf Railway.
#
# Voraussetzung: SUPABASE_SERVICE_KEY als Env-Var (NUR auf Railway setzen!
# Der lokale Mac/PC-Backend darf den Key nicht bekommen, sonst laufen zwei
# Wächter gegeneinander). Ohne Key bleibt der Wächter still inaktiv und das
# Frontend fällt automatisch auf die Browser-Erkennung zurück.
#
# Die Logik ist ein 1:1-Port von atCheck/mpWatch aus prophos.html:
#   - Baseline pro Plan (erster Blick zählt nur, triggert nie)
#   - Master-Fingerabdruck (eigene Master-Position ODER id_master auf der
#     Slave-Kopie) gegen Fehltrigger bei geteiltem Slave
#   - Close erst nach 2 Messungen IN FOLGE (Schutz gegen einzelne leere/
#     fehlerhafte Duplikum-Antworten, live beobachtet 07.07.2026)
#   - Mirror-Routen-Pläne (TopstepX-Master + MetaApi-Slave) ausgeschlossen —
#     die gehören dem lokalen Mirror, Duplikum kennt sie nicht
#   - Rate-Limit-Antworten (HTTP 200 mit error-Body statt data-Array) werden
#     als FEHLER behandelt, nie als "keine Positionen" (Lehre vom 30.07.2026)
#   - Alle Status-Writes mit Guard (status=eq.planned bzw. eq.open), damit
#     manuelle Aktionen im Frontend nie überschrieben werden
#   - P&L wird im Moment des Trade-Endes geholt und persistiert; für Review-
#     Pläne mit fehlendem P&L wird jede Runde nachversucht (max. 10x)
# ════════════════════════════════════════════════════════════════════════════
SUPABASE_URL = (os.environ.get("SUPABASE_URL") or "https://gxhkannmzpyuepxlepta.supabase.co").rstrip("/")
SUPABASE_SERVICE_KEY = (os.environ.get("SUPABASE_SERVICE_KEY")
                        or os.environ.get("SUPABASE_SERVICE_ROLE_KEY") or "").strip()
# 30s-Takt (07.08.2026, Finns neue Priorität: "Zeit ist mir nicht so wichtig —
# Hauptsache es funktioniert zu 100%, keine Bugs"). Bei 10 Duplikum-Konten sind
# 300 getOpenPositions/Stunde erlaubt; 30s-Takt = 120/h, also weniger als die
# Hälfte — massig Luft für Browser-Preflights, Balance-Polls und die P&L-Abfragen,
# statt permanent an der Kante zu fahren wie beim 4s-Experiment (das genau
# dadurch die Erkennung lahmlegte). Erkennungslatenz: Start ~30s, Ende ~60-90s.
# BEKANNTE GRENZE (dokumentiert, kein Bug — Review-Finding 07.08.): Ein Trade,
# der KÜRZER als ein Intervall läuft (Blitz-Scalp: auf und zu innerhalb ~30s),
# fällt komplett zwischen zwei Polls — der Plan bleibt auf "Geplant" und muss
# manuell nachgetragen werden. Bewusster Tausch gegen Zuverlässigkeit.
WATCHER_INTERVAL = max(10, int(os.environ.get("WATCHER_INTERVAL") or "30"))
WATCHER_DISABLED = bool(os.environ.get("WATCHER_DISABLED"))
# Leerlauf-Takt (01.10.2026, SUPABASE-DIÄT B): ohne geplanten/offenen Plan reicht eine Runde je Minute
WATCHER_LEERLAUF_S = max(WATCHER_INTERVAL, int(os.environ.get("WATCHER_LEERLAUF_S") or "60"))

_watcher_state = {}       # (uid, plan_id) -> {was_open, notified, baseline, streak, base_tickets, tickets}
_watcher_pnl_tries = {}   # (uid, plan_id) -> Anzahl P&L-Nachversuche
_watcher_pnl_next = {}    # (uid, plan_id) -> Epoch, ab wann der nächste gedrosselte
                          # P&L-Nachversuch erlaubt ist (nach den 10 schnellen)
_watcher_backoff = {}     # EMAIL -> {"until": epoch, "fails": n} — Login-Backoff (pro Duplikum-Konto)
_watcher_meta = {}        # uid -> {"links":..., "accs":..., "at": epoch} — 60s-Cache für dup_links/accounts
_watcher_tokens = {}      # EMAIL -> {"token":..., "at": epoch} — EIN Token pro Duplikum-Konto,
                          # egal wie viele Prophos-Profile es teilen (Finn hat 2 Profile
                          # auf derselben Duplikum-E-Mail — vorher wurde doppelt gepollt
                          # und doppelt eingeloggt)
_watcher_seen = {}        # EMAIL -> set(ticket) des letzten Ticks — für die Uhr-Kalibrierung
# Session-Pause je Duplikum-Konto (24.09.2026, Vollumstieg „Ohne Hedge" — Duplikum
# ist nur noch Rest-Abo; Finn: „riesen Umstieg — geh alles durch, Backend, jedes
# Einzelne"): läuft ein Abo aus oder fehlen die Zugangsdaten, kassiert der Wächter
# sonst jeden Zyklus (30 s) aufs Neue Login/401 — und schreibt das ins Log. Nach
# WT_PAUSE_FAILS Auth-Fehlschlägen in Folge (kein Token / 401 auch nach Re-Login)
# ruht das Konto WT_PAUSE_S lang, EIN Log-Satz „Duplikum-Session <mail>: pausiert
# bis …", danach ein Versuch je Pause. Netz-/Rate-Limit-Fehler zählen NICHT — die
# sind vorübergehend, und ein laufender Hedge-Plan braucht den nächsten Tick.
# V2-Pläne (mt5v2/tvv2) berührt der Wächter ohnehin nie (Filter in wt_check_user).
_watcher_pause = {}       # EMAIL -> {"fails": n, "until": epoch, "gemeldet": bool}
WT_PAUSE_FAILS = 3
WT_PAUSE_S = 30 * 60
_watcher_info = {"started": False, "last_run": 0, "runs": 0, "users": 0, "last_error": "", "cycle_ms": 0}
_watcher_thread_started = False
_watcher_memo_lock = threading.Lock()
_watcher_email_locks = {}   # email -> Lock (Single-Flight: teilen sich zwei Profile
                            # eine E-Mail, holt nur EIN Thread die Positionen)


# ── Duplikum-Rate-Budget (06.08.2026) ────────────────────────────────────────
# Duplikum limitiert PRO ENDPOINT und skaliert mit der Kontoanzahl des Duplikum-
# Kontos (offizielle Doku):
#   getOpenPositions:   min(1×n, 5)/s   min(2×n, 30)/min   min(30×n, 900)/h
#   getClosedPositions: min(1×n, 5)/s   min(2×n, 15)/min   min(30×n, 300)/h
# Finn: 10 Konten ⇒ 300 Abfragen/Stunde für getOpenPositions = eine alle 12s.
# Der 4s-Takt vom 05.08. lag mit 900/h dreifach drüber — Duplikum hat fast jeden
# Tick abgewiesen, deshalb wurden Trades „manchmal gar nicht" erkannt.
#
# Statt eines starren Intervalls ein Token-Bucket über echte Zeitfenster: solange
# Budget da ist, wird im schnellen Takt gepollt; ist es knapp, drosselt sich der
# Wächter selbst. Weil Finn stoßweise tradet (planen → ausführen → schließen,
# dazwischen Stunden Ruhe, in denen gar nicht gepollt wird), steht beim Trade
# fast immer das volle Kontingent bereit → schnelle Erkennung genau dann, wenn
# sie gebraucht wird.
DUP_ENDPOINT_LIMITS = {
    "position/getopenpositions.php":   {"sec": (1, 5), "min": (2, 30), "hour": (30, 900)},
    "position/getclosedpositions.php": {"sec": (1, 5), "min": (2, 15), "hour": (30, 300)},
}
DUP_BUDGET_HEADROOM = 0.85   # 15% Reserve für Browser-Preflights u.ä.
_dup_budget_hits = {}        # (email, path) -> [epoch, ...]
_dup_budget_block = {}       # (email, path) -> epoch, bis wann gesperrt (nach 429-artigem Fehler)
_dup_budget_lock = threading.Lock()
_dup_acct_count = {}         # email -> {"n": int, "at": epoch}
_dup_accounts_cache = {}     # email -> {"list": [{account_id,name,login}], "at": epoch} — fuer den dup_live-Spiegel


def _dup_limits_for(path, accounts):
    spec = DUP_ENDPOINT_LIMITS.get(str(path).lower())
    if not spec:
        return None
    n = max(1, int(accounts or 1))
    return {k: max(1, int(min(per * n, cap) * DUP_BUDGET_HEADROOM))
            for k, (per, cap) in spec.items()}


def _dup_budget_take(email, path, accounts):
    """True = darf senden (Zeitstempel wird gebucht). False = Budget erschöpft."""
    key = (str(email).lower(), str(path).lower())
    lim = _dup_limits_for(path, accounts)
    if not lim:
        return True
    now = time.time()
    with _dup_budget_lock:
        until = _dup_budget_block.get(key)
        if until and now < until:
            return False
        hits = _dup_budget_hits.setdefault(key, [])
        cutoff = now - 3600
        if hits and hits[0] < cutoff:
            hits[:] = [t for t in hits if t >= cutoff]
        if sum(1 for t in hits if t > now - 1) >= lim["sec"]:
            return False
        if sum(1 for t in hits if t > now - 60) >= lim["min"]:
            return False
        if len(hits) >= lim["hour"]:
            return False
        # Glättung: das Stundenkontingent anteilig über die Stunde verteilen,
        # sonst wäre es in 15 Minuten verbrannt und die restlichen 45 Minuten
        # liefe gar keine Erkennung (genau dann schließt der Trade dann).
        # 10 Konten ⇒ 255/h nutzbar ⇒ ~21 pro 5 Minuten ⇒ ein Poll alle ~14s.
        if sum(1 for t in hits if t > now - 300) >= max(2, lim["hour"] // 12):
            return False
        hits.append(now)
        return True


def _dup_budget_penalize(email, path, err):
    """Duplikum hat trotz eigener Buchführung ein Limit gemeldet (z.B. weil ein
    Browser parallel gepollt hat) → dieses Konto/Endpoint kurz sperren, statt
    weiter dagegen zu laufen. Fenster aus der Fehlermeldung abgeleitet."""
    key = (str(email).lower(), str(path).lower())
    low = str(err).lower()
    wait = 65 if "per minute" in low else (300 if "per hour" in low else 3)
    with _dup_budget_lock:
        _dup_budget_block[key] = time.time() + wait
    print(f"[watcher] ⏳ Duplikum-Limit für {email} ({path}) — pausiere {wait}s: {str(err)[:90]}", flush=True)


def _dup_budget_snapshot():
    """Nur aggregierte Zahlen (Endpoint → Polls letzte Stunde) — der Endpoint ist
    unauthentifiziert, also bewusst keine E-Mails nach außen."""
    now = time.time()
    out = {}
    with _dup_budget_lock:
        for (_email, path), hits in _dup_budget_hits.items():
            out[path] = out.get(path, 0) + sum(1 for t in hits if t > now - 3600)
    return out


def wt_account_count(email, token):
    """Anzahl Trading-Konten dieses Duplikum-Kontos — bestimmt die Rate-Limits.
    Einmal pro Stunde abgefragt (eigener Endpoint, eigenes Budget)."""
    e = str(email).lower()
    hit = _dup_acct_count.get(e)
    if hit and (time.time() - hit["at"]) < 3600:
        return hit["n"]
    # Bewusst KLEINER Default (Review-Finding): mit einem zu großen Wert wäre das
    # Budget zu großzügig und wir liefen dauerhaft in Duplikums echtes Limit —
    # genau der Zustand, der heute die Erkennung lahmgelegt hat. Lieber zu langsam
    # als blind. Und ein fehlgeschlagener Abruf wird NICHT eine Stunde gecacht.
    n, ok = 3, False
    try:
        r = requests.post(f"{DUP_BASE}/account/getAccounts.php", data={"length": "1000"},
                          headers={"Authorization": f"Bearer {token}"}, timeout=15)
        d = r.json() if r.status_code == 200 else {}
        # Duplikium liefert die Liste je nach Endpoint unter "data" ODER
        # "accounts" — das Frontend liest getAccounts seit jeher als
        # res.data.accounts. Der alte reine data-Check griff ins Leere: n blieb
        # ewig auf dem Default und der dup_live-Spiegel ohne Namen (Fund
        # 25.08.2026: acc_anzahl blieb 0, waehrend die Positionen flossen).
        lst = None
        if isinstance(d, dict):
            lst = d.get("data") if isinstance(d.get("data"), list) else d.get("accounts")
        if isinstance(lst, list):
            n, ok = max(1, len(lst)), True
            # Fuer den dup_live-Spiegel (25.08.2026): Name/Login pro Account —
            # gleiche Antwort, kein zusaetzlicher Duplikium-Call.
            # balance/ccy seit 15.09.2026 mit im Spiegel (Finn: Balance neben
            # den Winning-Days-Accounts im Admin) — dieselbe Antwort, kein
            # zusaetzlicher Call; /admin/overview loest darueber die Balance
            # von Tradovate-Mastern auf (login = external_id des Accounts).
            _dup_accounts_cache[e] = {"at": time.time(), "list": [
                {"account_id": a.get("account_id"), "name": a.get("name"), "login": a.get("login"),
                 "balance": a.get("balance"), "ccy": a.get("ccy")}
                for a in lst if isinstance(a, dict)]}
    except Exception:
        pass
    if ok:
        _dup_acct_count[e] = {"n": n, "at": time.time()}
    else:
        # Kurz zwischenspeichern, damit nicht jeder Tick erneut anfragt, aber bald
        # wieder versuchen (statt eine Stunde mit dem Default zu rechnen).
        _dup_acct_count[e] = {"n": (hit or {}).get("n", n), "at": time.time() - 3300}
    return _dup_acct_count[e]["n"]


def _wt_email_lock(email):
    with _watcher_memo_lock:
        lk = _watcher_email_locks.get(email)
        if lk is None:
            # RLock: wt_email_token lockt selbst und wird auch aus bereits
            # gelocktem Kontext (_wt_memo_positions_locked) gerufen — ein
            # normales Lock wäre dort ein Deadlock.
            lk = threading.RLock()
            _watcher_email_locks[email] = lk
        return lk
# Duplikums Zeitstempel (openTime/closeTime) kommen OHNE Zeitzone. Der Offset zur
# echten UTC wird zur Laufzeit kalibriert: wenn der Wächter einen Trade-START erkennt,
# ist die neue Position höchstens ~2 Ticks alt → parse(openTime) − jetzt ≈ Offset.
# Solange unkalibriert, rechnen Vergleiche mit großzügiger Toleranz.
_dup_clock = {"offset": None}   # Sekunden: naiver Duplikum-Zeitstempel − echte UTC


def _sb_headers(prefer=None):
    h = {
        "apikey": SUPABASE_SERVICE_KEY,
        "Authorization": f"Bearer {SUPABASE_SERVICE_KEY}",
        "Content-Type": "application/json",
    }
    if prefer:
        h["Prefer"] = prefer
    return h


# ══ SUPABASE-BREMSE (01.10.2026, Supabase-Ausfall 30.09.: 11:24–20:12 UTC hing jede Anfrage 12 s und mehr, bei 48 Threads bis zu
# 48 gleichzeitig; Routen mit mehreren Abfragen hielten einen Thread bis ~90 s, die Reader schickten alle 2 s nach). Eine Sicherung
# je Dienst (rest, auth): nach SB_BREMSE_N Fehlern in Folge (Timeout, Verbindungsfehler, 5xx) 30 → 60 → 120 s lang keine Anfrage
# mehr — SupabaseGesperrt sofort statt Warten —, danach genau EINE Mini-Probe; ihr Erfolg schließt die Sicherung. 4xx zählen nicht
# (die DB hat geantwortet). Nachzügler (Anfragen, die schon liefen) verlängern nichts. Der Lock gilt nur für den Zustand, nie für
# den Netz-Aufruf. Wirkt unter sync- und gthread-Worker gleich (Zustand im Prozess, --workers 1). kritisch=True geht immer durch
# (/puls-ergebnis: der Bot wiederholt nicht, ein verlorenes Ergebnis hieße Plan „Geplant" bei offener Position).
SB_BREMSE_N = 4
SB_BREMSE_STUFEN = (30, 60, 120)
SB_BREMSE_HALB_S = 5               # Rückmeldung an Wartende, während die Probe läuft (Retry-After nie 0)
SB_TIMEOUT = (5, 12)               # Verbindungsaufbau / Lesen — vorher 12 s je Phase
SB_PROBE_TIMEOUT = (3, 5)


class SupabaseGesperrt(requests.exceptions.ConnectionError):
    """Sicherung offen: die Anfrage wurde gar nicht gesendet. Erbt von ConnectionError, damit jedes bestehende except greift."""
    sb_netz = True

    def __init__(self, rest_s=0.0, dienst="rest"):
        super().__init__(f"Supabase-Bremse offen ({dienst}, noch {int(max(0, rest_s))} s)")
        self.rest_s, self.dienst = float(max(0.0, rest_s)), dienst


def sb_bremse_neu():
    return {"folge": 0, "stufe": -1, "offen_bis": 0.0, "probe": False, "seit": 0.0, "abgewiesen": 0, "letzter": ""}


def sb_bremse_vorher(z, jetzt, kritisch=False):
    """REIN RECHNEND (testbar): vor einer Anfrage → ('frei'|'probe'|'zu', rest_s). 'probe' bekommt genau einer."""
    if kritisch or z["stufe"] < 0:
        return "frei", 0.0
    if jetzt < z["offen_bis"]:
        return "zu", z["offen_bis"] - jetzt
    if not z["probe"]:
        return "probe", 0.0
    return "zu", float(SB_BREMSE_HALB_S)


def sb_bremse_nach(z, jetzt, ok, probe=False, fehler=""):
    """REIN RECHNEND (testbar): Ergebnis einer Anfrage in den Zustand. Erfolg schließt; ein Probe-Fehler geht eine Stufe höher;
    im offenen Zustand zählen andere Fehler nicht (Nachzügler); sonst öffnet der SB_BREMSE_N-te Fehler in Folge."""
    if ok:
        z.update(folge=0, stufe=-1, offen_bis=0.0, probe=False, seit=0.0)
        return z
    if fehler:
        z["letzter"] = str(fehler)[:120]
    if probe:
        z["stufe"] = min(z["stufe"] + 1, len(SB_BREMSE_STUFEN) - 1)
        z["offen_bis"], z["probe"] = jetzt + SB_BREMSE_STUFEN[z["stufe"]], False
        return z
    if z["stufe"] >= 0:
        return z
    z["folge"] += 1
    if z["folge"] >= SB_BREMSE_N:
        z.update(stufe=0, offen_bis=jetzt + SB_BREMSE_STUFEN[0], seit=jetzt)
    return z


_SB_BREMSE = {"rest": sb_bremse_neu(), "auth": sb_bremse_neu()}
_SB_BREMSE_LOCK = threading.Lock()
_SB_GEHEILT_AT = {"rest": 0.0, "auth": 0.0}     # wann die Sicherung zuletzt von gesperrt auf normal ging (Reader-Wacht-Karenz)


def _sb_bremse_melden(dienst, ok, probe=False, fehler=""):
    with _SB_BREMSE_LOCK:
        z = _SB_BREMSE[dienst]
        war = z["stufe"]
        sb_bremse_nach(z, time.time(), ok, probe=probe, fehler=fehler)
        if war >= 0 and z["stufe"] < 0:
            _SB_GEHEILT_AT[dienst] = time.time()
            print(f"[sb-bremse] ✅ {dienst}: Supabase antwortet wieder — Sicherung zu", flush=True)
        elif war < 0 and z["stufe"] >= 0:
            print(f"[sb-bremse] ⛔ {dienst}: {SB_BREMSE_N} Fehler in Folge ({z['letzter']}) — {SB_BREMSE_STUFEN[0]} s gesperrt", flush=True)


def schleifen_pause(normal_s, fehler_n, rest_s, deckel_s, verdoppeln=True):
    """REIN RECHNEND (testbar): Pause einer Hintergrund-Schleife. Ohne DB-Fehler normal_s; mit n DB-Fehlern in Folge
    normal·2^n (verdoppeln) bzw. normal, mindestens bis die Sicherung wieder fragt (rest_s), höchstens deckel_s."""
    if fehler_n <= 0:
        return float(normal_s)
    basis = normal_s * (2 ** min(int(fehler_n), 10)) if verdoppeln else normal_s
    return float(min(deckel_s, max(basis, rest_s, normal_s)))


def _ist_db_fehler(e):
    return bool(getattr(e, "sb_netz", False)) or _SB_BREMSE["rest"]["stufe"] >= 0


def _schleife_schlafen(sek, db_pause=False):
    """Schläft sek Sekunden in 5-s-Schritten. db_pause: aufwachen, sobald die Sicherung wieder zu ist (Supabase antwortet)."""
    ende = time.time() + sek
    while True:
        rest = ende - time.time()
        if rest <= 0:
            return
        time.sleep(min(rest, 5.0))
        if db_pause and _SB_BREMSE["rest"]["stufe"] < 0:
            return


def sb_bremse_stand(jetzt=None):
    """Zustand für /health und /watcher/status — nur Zahlen, keine Fehlertexte nach außen (Endpunkte sind offen)."""
    jetzt = time.time() if jetzt is None else jetzt
    with _SB_BREMSE_LOCK:
        out = {}
        for d, z in _SB_BREMSE.items():
            art = "normal" if z["stufe"] < 0 else ("probe" if z["probe"] or jetzt >= z["offen_bis"] else "gesperrt")
            out[d] = {"zustand": art, "rest_s": int(max(0, z["offen_bis"] - jetzt)) if z["stufe"] >= 0 else 0,
                      "folge": z["folge"], "stufe": z["stufe"], "seit_s": int(jetzt - z["seit"]) if z["seit"] else 0,
                      "abgewiesen": z["abgewiesen"]}
        return out


def sb_bremse_rest_s(dienst="rest"):
    """Sekunden, bis die Sicherung wieder eine Anfrage (bzw. die Probe) zulässt; 0 = normal."""
    with _SB_BREMSE_LOCK:
        z = _SB_BREMSE[dienst]
        return max(0.0, z["offen_bis"] - time.time()) if z["stufe"] >= 0 else 0.0


def _sb_probe(dienst):
    """Mini-Probe mit kurzem Zeitlimit — True, wenn der Dienst überhaupt antwortet (< 500). Wirft nie."""
    try:
        if dienst == "auth":
            r = requests.get(f"{SUPABASE_URL}/auth/v1/health", headers={"apikey": SUPABASE_SERVICE_KEY}, timeout=SB_PROBE_TIMEOUT)
        else:
            r = requests.get(f"{SUPABASE_URL}/rest/v1/wd_farmer_regeln", params={"select": "id", "limit": "1"},
                             headers=_sb_headers(), timeout=SB_PROBE_TIMEOUT)
        return r.status_code < 500
    except Exception:
        return False


def _sb_anfrage(methode, url, dienst="rest", kritisch=False, timeout=None, **kw):
    """requests.request hinter der Sicherung → Response (Aufrufer prüft den Status selbst, wie bisher). Netzfehler und 5xx
    zählen; ausgelöste Ausnahmen tragen sb_netz=True."""
    with _SB_BREMSE_LOCK:
        z = _SB_BREMSE[dienst]
        aktion, rest = sb_bremse_vorher(z, time.time(), kritisch)
        if aktion == "probe":
            z["probe"] = True
        elif aktion == "zu":
            z["abgewiesen"] += 1
    if aktion == "zu":
        raise SupabaseGesperrt(rest, dienst)
    if aktion == "probe":
        ok = False
        try:
            ok = _sb_probe(dienst)
        finally:
            _sb_bremse_melden(dienst, ok, probe=True, fehler="" if ok else "probe")
        if not ok:
            raise SupabaseGesperrt(sb_bremse_rest_s(dienst), dienst)
    try:
        r = requests.request(methode, url, timeout=timeout or SB_TIMEOUT, **kw)
    except requests.exceptions.RequestException as e:
        _sb_bremse_melden(dienst, False, fehler=type(e).__name__)
        e.sb_netz = True
        raise
    _sb_bremse_melden(dienst, r.status_code < 500, fehler=f"http {r.status_code}")
    return r


def _sb_pruefen(r):
    """raise_for_status wie bisher; 5xx zusätzlich als Netz-/DB-Fehler markiert (Schleifen und Rückfall-Lesungen unterscheiden so)."""
    try:
        r.raise_for_status()
    except requests.exceptions.HTTPError as e:
        if r.status_code >= 500:
            e.sb_netz = True
        raise


def sb_select(table, params):
    r = _sb_anfrage("GET", f"{SUPABASE_URL}/rest/v1/{table}", params=params, headers=_sb_headers())
    _sb_pruefen(r)
    return r.json()


def sb_update(table, params, body):
    """PATCH mit return=representation → Liste der WIRKLICH geänderten Zeilen.
    Leere Liste = Guard hat gegriffen (z.B. Status wurde inzwischen manuell
    geändert) — das ist ein normales Ergebnis, kein Fehler."""
    r = _sb_anfrage("PATCH", f"{SUPABASE_URL}/rest/v1/{table}", params=params, json=body,
                    headers=_sb_headers("return=representation"))
    _sb_pruefen(r)
    return r.json()


def sb_delete(table, params):
    """DELETE mit return=representation → Liste der WIRKLICH gelöschten Zeilen (leer = Guard hat gegriffen). 07.10.2026 für die
    Admin-Eingriffe des Trade-Planers (Vorschläge fremder IDs löschen) — der Aufrufer legt den Guard in params."""
    r = _sb_anfrage("DELETE", f"{SUPABASE_URL}/rest/v1/{table}", params=params, headers=_sb_headers("return=representation"))
    _sb_pruefen(r)
    return r.json()


def sb_upsert(table, body, kritisch=False):
    """POST mit merge-duplicates = Upsert auf den Primary Key (Service-Key,
    an RLS vorbei). Fuer den dup_live-Spiegel (25.08.2026). kritisch=True: an der Supabase-Bremse vorbei."""
    r = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/{table}", kritisch=kritisch, json=body,
                    headers=_sb_headers("resolution=merge-duplicates,return=minimal"))
    _sb_pruefen(r)


# ── Kurz-Caches für Login-Prüfung & Co. (01.10.2026, SUPABASE-DIÄT B) ───────────────────────────────────────────────────────
# Lage: Compute NANO (0,5 GB), die DB hing in Wellen (12:10/12:30/12:50 UTC, PGRST003 „Timed out acquiring connection").
# Edge-Logs 09:00–12:50 UTC, nur dieses Backend: auth/v1/user 504, auth/v1/admin/users 487, admin_zugang 490,
# duplikum_credentials 462 — fast alles dieselbe Antwort im Abstand von Sekunden (jeder PC-Tab fragt /admin/live-trades
# alle 55–70 s, jede Anfrage prüfte das Login neu, holte admin_zugang und die komplette Nutzerliste).
# Regeln: nur ERFOLGE werden gemerkt (401/5xx/Netzfehler nie — die nächste Anfrage fragt wieder), Login je Token-Hash
# höchstens 45 s und nie über das exp des Tokens hinaus; ein abgemeldetes Token gilt also höchstens 45 s weiter.
# Kein Lesen auf Vorrat — die Caches füllen sich nur, wenn sowieso gefragt wird.
AUTH_USER_CACHE_S = 45
AUTH_LISTE_CACHE_S = 60
_auth_user_cache = {}       # sha256(token) → (bis_epoch, user_dict)
_auth_liste_cache = {"bis": 0.0, "users": None}
_admin_zugang_cache = {}    # uid → (bis_epoch, nur_eigene)
_dup_creds_cache = {"bis": 0.0, "rows": None}
_kurz_cache_lock = threading.Lock()


class _CacheAntwort:
    """Antwort-Attrappe mit status_code/json() — damit die Aufrufer unverändert r.status_code / r.json() lesen."""
    def __init__(self, status_code, daten):
        self.status_code = status_code
        self._daten = daten

    def json(self):
        return self._daten


def _jwt_exp(token):
    """exp-Claim (epoch) aus dem JWT lesen, OHNE Prüfung — nur als Obergrenze für den Cache. 0 = unbekannt."""
    try:
        teil = token.split(".")[1]
        teil += "=" * (-len(teil) % 4)
        return float(json.loads(base64.urlsafe_b64decode(teil.encode())).get("exp") or 0)
    except Exception:
        return 0.0


def auth_cache_bis(jetzt, exp, dauer_s=AUTH_USER_CACHE_S):
    """REIN RECHNEND (testbar): bis wann ein bestätigtes Login gemerkt wird — jetzt+dauer_s, aber nie über exp hinaus."""
    bis = jetzt + dauer_s
    return min(bis, exp) if exp else bis


def _auth_user_anfrage(token):
    """GET /auth/v1/user mit 45-s-Cache je Token. Rückgabe wie _sb_anfrage (status_code/json()); Ausnahmen wie bisher."""
    schluessel = hashlib.sha256(token.encode()).hexdigest()
    jetzt = time.time()
    with _kurz_cache_lock:
        treffer = _auth_user_cache.get(schluessel)
        if treffer and treffer[0] > jetzt:
            return _CacheAntwort(200, treffer[1])
    r = _sb_anfrage("GET", f"{SUPABASE_URL}/auth/v1/user", dienst="auth", timeout=12,
                     headers={"apikey": SUPABASE_ANON_KEY, "Authorization": f"Bearer {token}"})
    if r.status_code == 200:
        try:
            u = r.json() or {}
        except Exception:
            u = {}
        bis = auth_cache_bis(jetzt, _jwt_exp(token))
        if u.get("id") and bis > jetzt:
            with _kurz_cache_lock:
                if len(_auth_user_cache) > 500:   # Abgelaufenes wegräumen, Deckel gegen schleichendes Wachsen
                    for k in [k for k, v in _auth_user_cache.items() if v[0] <= jetzt] or list(_auth_user_cache)[:250]:
                        _auth_user_cache.pop(k, None)
                _auth_user_cache[schluessel] = (bis, u)
    return r


def _auth_liste_anfrage():
    """GET /auth/v1/admin/users?per_page=200 mit 60-s-Cache (Namen/E-Mails ändern sich praktisch nie). Rückgabe wie
    _sb_anfrage; gemerkt wird nur eine 200er-Antwort mit mindestens einem Nutzer."""
    jetzt = time.time()
    with _kurz_cache_lock:
        if _auth_liste_cache["users"] is not None and _auth_liste_cache["bis"] > jetzt:
            return _CacheAntwort(200, {"users": _auth_liste_cache["users"]})
    r = _sb_anfrage("GET", f"{SUPABASE_URL}/auth/v1/admin/users?per_page=200", dienst="auth",
                     headers=_sb_headers(), timeout=12)
    if r.status_code == 200:
        try:
            users = (r.json() or {}).get("users")
        except Exception:
            users = None
        if isinstance(users, list) and users:
            with _kurz_cache_lock:
                _auth_liste_cache.update(bis=jetzt + AUTH_LISTE_CACHE_S, users=users)
    return r


def admin_zugang_nur_eigene(uid):
    """admin_zugang.nur_eigene je uid, 60 s gemerkt. Fehler werfen wie sb_select (der Aufrufer antwortet 502)."""
    jetzt = time.time()
    with _kurz_cache_lock:
        treffer = _admin_zugang_cache.get(uid)
        if treffer and treffer[0] > jetzt:
            return treffer[1]
    z = sb_select("admin_zugang", {"select": "nur_eigene", "user_id": f"eq.{uid}"})
    nur = bool(isinstance(z, list) and z and z[0].get("nur_eigene"))
    with _kurz_cache_lock:
        _admin_zugang_cache[uid] = (jetzt + AUTH_LISTE_CACHE_S, nur)
    return nur


def dup_creds_lesen():
    """duplikum_credentials (select *) mit 60-s-Cache — Wächter-Zyklus (30 s) und /duplikum/session teilen sich die Zeilen.
    Die Zugänge ändern sich nur beim Verbinden/Trennen im Frontend; der Token lebt ohnehin im Speicher (_watcher_tokens).
    Gibt eine flache Kopie der Liste zurück (Aufrufer filtern sie)."""
    jetzt = time.time()
    with _kurz_cache_lock:
        if _dup_creds_cache["rows"] is not None and _dup_creds_cache["bis"] > jetzt:
            return list(_dup_creds_cache["rows"])
    rows = sb_select("duplikum_credentials", {"select": "*"})
    if isinstance(rows, list):
        with _kurz_cache_lock:
            _dup_creds_cache.update(bis=jetzt + AUTH_LISTE_CACHE_S, rows=rows)
        return list(rows)
    return rows




