# KAUFPLAN (31.08.2026, Finns Wunsch) — welche Accounts sollen kuenftig auf
# welcher ID gekauft werden. Loest die Google-Keep-Notiz ab, in der das bisher
# als Freitext stand ("Finn / Apex Funded (1k - revolut) / Tradeify Funded ...").
#
# Warum ueber app.py und nicht direkt aus dem Browser wie die Kasse: der Plan
# sagt, was fuer FREMDE IDs gekauft werden soll und was es kosten darf. Die
# Kasse teilen sich alle Eingeloggten absichtlich, dieser Plan nicht — er haengt
# deshalb an _admin_auth() (ADMIN_EMAILS) und die Tabelle hat gar keine
# RLS-Policy, kommt also fuer keinen Client direkt in Frage.
# ════════════════════════════════════════════════════════════════════════════

# Nur diese Felder duerfen vom Client kommen — Whitelist statt Durchreichen.
ACC_PLAN_FELDER = ("firma", "notiz", "erledigt")


def acc_plan_stand(accs, user_id, firma, archiviert):
    """Was steht AKTUELL auf dieser ID bei dieser Firma? -> {typ: anzahl}.

    Ersetzt seit Finns "mach das viel simpler" (31.08.2026) das ganze
    Ziel-Modell: kein Zielzustand, keine Anzahl, keine Groesse. Der Eintrag ist
    eine Notiz ("bis 1x 150k funded steht"), und daneben steht ungefragt, was
    da wirklich liegt. Genau daran sieht Finn, ob er weiterkaufen muss — und
    es kostet ihn kein Eingabefeld.

    Archivierte zaehlen nicht mit: ein geblowter Account ist nicht mehr da."""
    stand = {}
    for a in accs:
        if str(a.get("user_id")) != str(user_id):
            continue
        if str(a.get("id")) in archiviert:
            continue
        if _firm_norm(a.get("firm")) != _firm_norm(firma):
            continue
        t = str(a.get("account_type") or "?")
        stand[t] = stand.get(t, 0) + 1
    return stand


def _acc_plan_body(daten, neu):
    """Rohes JSON -> saubere Spaltenwerte. (body, fehlertext)."""
    out = {}
    if neu:
        uid = str(daten.get("user_id") or "").strip()
        if len(uid) < 10:
            return None, "user_id fehlt"
        out["user_id"] = uid
    for f in ACC_PLAN_FELDER:
        if f not in daten:
            continue
        if f == "erledigt":
            out[f] = bool(daten[f])
            # Datum haengt am Haken, nicht an einem zweiten Klick — sonst steht
            # spaeter "erledigt" ohne Zeitpunkt da.
            out["erledigt_am"] = datetime.now(timezone.utc).isoformat() if out[f] else None
        else:
            out[f] = str(daten[f] if daten[f] is not None else "").strip()[:400]
    if neu and not out.get("firma"):
        return None, "Firma angeben"
    return out, None


def _acc_plan_personen(accs):
    """[{user_id, name, mail}] — alle Personen, die Accounts besitzen.
    Ausgeblendete Personen (ADMIN_EXCLUDE_EMAILS) fliegen raus, sonst waere der
    Kaufplan das Schlupfloch an der Ausblendung vorbei."""
    ids = {str(a.get("user_id")) for a in accs if a.get("user_id")}
    namen, mails = {}, {}
    try:
        r = _auth_liste_anfrage()
        for u in (r.json() or {}).get("users", []):
            uid = str(u.get("id"))
            mail = str(u.get("email") or "")
            mails[uid] = mail
            meta = str((u.get("user_metadata") or {}).get("name") or "").strip()
            namen[uid] = meta or (mail.split("@")[0] if "@" in mail else uid[:8])
    except Exception as e:
        # Supabase gestört/gesperrt (01.10.2026, AUSFALL-BREMSE): weiterwerfen (→ 502 beim Aufrufer) — sonst fehlten die Mails und
        # ADMIN_EXCLUDE_EMAILS filterte niemanden heraus; bis zu 120 s am Stück, wenn nur die Auth-Sicherung offen ist
        if getattr(e, "sb_netz", False):
            raise
    out = []
    for uid in ids:
        if str(mails.get(uid, "")).strip().lower() in ADMIN_EXCLUDE_EMAILS:
            continue
        out.append({"user_id": uid, "name": namen.get(uid, uid[:8]), "mail": mails.get(uid, "")})
    return sorted(out, key=lambda p: p["name"].lower())


def _acc_plan_archiviert():
    """Menge archivierter Account-IDs — derselbe Weg wie in /admin/overview
    (user_settings key='archive', aus dem localStorage gesynct)."""
    aus = set()
    try:
        for r in _sb_all("user_settings", {"select": "value", "key": "eq.archive"}):
            v = r.get("value")
            if isinstance(v, str):
                try: v = json.loads(v)
                except Exception: v = None
            if isinstance(v, dict):
                for acc_id, info in v.items():
                    if (isinstance(info, dict) and info.get("archived")) or (info and not isinstance(info, dict)):
                        aus.add(str(acc_id))
    except Exception as e:
        print(f"[accplan] ⚠️ Archiv-Status: {type(e).__name__}: {e}", flush=True)
    return aus


@app.route("/admin/acc-plan", methods=["GET", "POST", "PATCH", "DELETE", "OPTIONS"])
def admin_acc_plan():
    if request.method == "OPTIONS":
        return "", 200
    mail, err = _admin_auth()
    if err:
        return err

    if request.method == "GET":
        try:
            ziele = sb_select("acc_plan", {
                "select": "*", "order": "created_at.desc", "limit": "500"})
            accs = _sb_all("accounts", {"select": "id,user_id,name,firm,account_type"})
            archiv = _acc_plan_archiviert()
            for z in ziele:
                z["stand"] = acc_plan_stand(accs, z.get("user_id"), z.get("firma"), archiv)
            # Firmen-Vorschlaege aus dem Bestand: Finn soll die Firma auswaehlen,
            # nicht tippen. Bewusst als Vorschlagsliste und nicht als harte
            # Auswahl — eine Firma, bei der er noch keinen Account hat, ist
            # genau der Fall, den man plant.
            firmen = sorted({_firm_norm(a.get("firm")) for a in accs
                             if (a.get("firm") or "").strip()} - {"—"})
            return jsonify({"eintraege": ziele, "firmen": firmen,
                            "personen": _acc_plan_personen(accs)})
        except Exception as e:
            print(f"[accplan] ⚠️ laden: {type(e).__name__}: {e}", flush=True)
            return jsonify({"error": f"Kaufplan nicht ladbar ({type(e).__name__})"}), 502

    daten = request.get_json(silent=True) or {}

    if request.method == "POST":
        body, f = _acc_plan_body(daten, neu=True)
        if f:
            return jsonify({"error": f}), 400
        body["created_by"] = mail
        try:
            return jsonify({"eintrag": sb_insert("acc_plan", body)})
        except Exception as e:
            print(f"[accplan] ⚠️ anlegen: {type(e).__name__}: {e}", flush=True)
            return jsonify({"error": f"Nicht angelegt ({type(e).__name__})"}), 502

    pid = str(daten.get("id") or request.args.get("id") or "").strip()
    if len(pid) < 10:
        return jsonify({"error": "id fehlt"}), 400

    if request.method == "DELETE":
        try:
            _sb_anfrage("DELETE", f"{SUPABASE_URL}/rest/v1/acc_plan",
                            params={"id": f"eq.{pid}"},
                            headers=_sb_headers(), timeout=12).raise_for_status()
            return jsonify({"ok": True})
        except Exception as e:
            print(f"[accplan] ⚠️ loeschen: {type(e).__name__}: {e}", flush=True)
            return jsonify({"error": f"Nicht geloescht ({type(e).__name__})"}), 502

    body, f = _acc_plan_body(daten, neu=False)
    if f:
        return jsonify({"error": f}), 400
    if not body:
        return jsonify({"error": "Nichts zu aendern"}), 400
    body["updated_at"] = datetime.now(timezone.utc).isoformat()
    try:
        zeilen = sb_update("acc_plan", {"id": f"eq.{pid}"}, body)
        if not zeilen:
            return jsonify({"error": "Eintrag nicht gefunden"}), 404
        return jsonify({"eintrag": zeilen[0]})
    except Exception as e:
        print(f"[accplan] ⚠️ aendern: {type(e).__name__}: {e}", flush=True)
        return jsonify({"error": f"Nicht geaendert ({type(e).__name__})"}), 502


