@app.route("/admin/auto-plan", methods=["GET", "POST", "OPTIONS"])
def admin_auto_plan():
    """GET: letzter Lauf (Admin: alle IDs, sonst nur die eigene). POST {trocken, tag}: jetzt planen — Admin oder eine ID,
    die selbst im Auto-Planer ist (Finn bestätigt in den Test-IDs, deren Login ist kein Admin).
    POST {trocken:true, ids:"alle"}: Probelauf über alle IDs mit planbaren Konten — nur Admin (ap_ids_modus, 07.10.2026)."""
    if request.method == "OPTIONS":
        return "", 200
    mail, err = _admin_auth()
    uid = request.environ.get("prophos.admin_uid")
    admin = err is None
    if not admin:
        if err[1] != 403:
            return err
        uid, err2 = _wd_login()
        if err2:
            return err2
    reg = (sb_select("auto_plan_regeln", {"select": "aktiv,user_ids", "id": "eq.1"}) or [{}])[0]
    im_planer = str(uid) in [str(u) for u in (reg.get("user_ids") or [])]
    if not admin and not im_planer:
        return jsonify({"ok": False, "msg": "Diese ID ist nicht im Auto-Planer"}), 403
    sicht = None if admin else str(uid)        # 06.10.2026: Nicht-Admin (Test-ID) sieht nur die eigenen Zeilen
    if request.method == "GET":
        sicht = _ap_sicht_aus_anfrage(admin, uid)   # seit 08.10.2026: Nicht-Admin alle IDs nur mit ?sicht=admin (Admin-Reiter), sonst eigene
        rows = sb_select("auto_plan_lauf", {"select": "tag,quelle,at,ergebnis", "order": "at.desc", "limit": "1"})
        erg = (rows[0].get("ergebnis") if rows else None) or {}
        return jsonify({"ok": True, "admin": admin, "aktiv": bool(reg.get("aktiv")), "ids": len(reg.get("user_ids") or []),
                        "im_planer": im_planer or admin, "letzter": ap_sicht(erg, sicht) if sicht else erg,
                        "sicht": "eigene" if sicht else "alle", "info": _ap_info})
    body = request.get_json(silent=True) or {}
    tag = str(body.get("tag") or "").strip() or None
    if tag and not re.match(r"^\d{4}-\d{2}-\d{2}$", tag):
        return jsonify({"ok": False, "msg": "tag = JJJJ-MM-TT"}), 400
    seed = body.get("seed")
    if seed not in (None, "") and not re.match(r"^\d{1,10}$", str(seed)):
        return jsonify({"ok": False, "msg": "seed = Ganzzahl"}), 400
    ids, fehler = ap_ids_modus(body, admin)         # PROBELAUF-ALLE-IDS (07.10.2026): ids="alle" nur Admin, nur trocken
    if fehler:
        return jsonify({"ok": False, "admin": admin, "msg": fehler[0]}), fehler[1]
    try:
        erg = ap_planen(tag, trocken=bool(body.get("trocken")), quelle="hand", seed=seed, sicht_uid=sicht,
                        fingerabdruck=str(body.get("fingerabdruck") or "").strip() or None, ids=ids)
        return jsonify(dict(erg, admin=admin))
    except Exception as e:
        return jsonify({"ok": False, "admin": admin, "msg": f"{type(e).__name__}: {e}"}), 502


